-- Sinh tự động bởi scripts/build_supabase_seed.js
delete from questions;
insert into questions(id,chapter,chapter_name,question,image,options,correct_option,is_critical,explanation) values
(1,1,'Quy định chung và quy tắc giao thông đường bộ','Phần của đường bộ được sử dụng cho phương tiện giao thông đường bộ đi lại là gì?',null,'["Phần mặt đường và lề đường.","Phần đường xe chạy.","Phần đường xe cơ giới."]'::jsonb,2,false,'Theo Luật Trật tự, an toàn giao thông đường bộ, ''Phần đường xe chạy'' là phần của đường bộ được sử dụng cho phương tiện giao thông đường bộ đi lại. Phần lề đường chỉ dùng để dừng, đỗ xe hoặc cho người đi bộ khi cần thiết, không phải phần đường xe chạy.'),
(2,1,'Quy định chung và quy tắc giao thông đường bộ','Làn đường là gì?',null,'["Là một phần của phần đường xe chạy được chia theo chiều dọc của đường, sử dụng cho xe chạy.","Là một phần của phần đường xe chạy được chia theo chiều dọc của đường, có đủ chiều rộng cho xe chạy an toàn.","Là đường cho xe ô tô chạy, dừng, đỗ an toàn."]'::jsonb,2,false,'''Làn đường'' là một phần của phần đường xe chạy được chia theo chiều dọc của đường, có đủ chiều rộng cho xe chạy an toàn. Điểm mấu chốt bắt buộc phải có là ''có đủ chiều rộng cho xe chạy an toàn''.'),
(3,1,'Quy định chung và quy tắc giao thông đường bộ','Khổ giới hạn của đường bộ được hiểu như thế nào là đúng?',null,'["Khổ giới hạn của đường bộ là khoảng trống có kích thước giới hạn về chiều rộng, chiều cao của đường bộ để các xe, bao gồm cả hàng hoá xếp trên xe đi qua được an toàn và được xác định theo quy chuẩn, tiêu chuẩn kỹ thuật của đường bộ.","Là khoảng trống có kích thước giới hạn về chiều rộng của đường, cầu, bến phà, hầm trên đường b ộ để các xe kể cả hàng hóa xếp trên xe đi qua được an toàn.","Là khoảng trống có kích thước giới hạn về chiều cao của cầu, bến phà, hầm trên đường bộ để các xe đi qua được an toàn."]'::jsonb,1,false,'''Khổ giới hạn của đường bộ'' là khoảng trống có kích thước giới hạn về cả CHIỀU RỘNG và CHIỀU CAO của đường bộ để các phương tiện (bao gồm cả hàng hoá xếp trên xe) lưu thông qua an toàn theo quy chuẩn kỹ thuật.'),
(4,1,'Quy định chung và quy tắc giao thông đường bộ','Dải phân cách được lắp đặt để làm gì?',null,'["Để phân chia các làn đường dành cho xe cơ giới và xe thô sơ trên đường cao tốc.","Để phân chia phần đường xe chạy thành hai chiều riêng biệt hoặc để phân chia phần đường dành cho xe cơ giới và xe thô sơ hoặc của nhiều loại xe khác nhau trên cùng một chiều đường.","Để phân tách phần đường xe chạy và hành lang an toàn giao thông."]'::jsonb,2,false,'''Dải phân cách'' là bộ phận của đường để phân chia phần đường xe chạy thành hai chiều riêng biệt hoặc để phân chia phần đường dành cho xe cơ giới và xe thô sơ hoặc các loại xe khác nhau trên cùng một chiều đường.'),
(5,1,'Quy định chung và quy tắc giao thông đường bộ','Vạch kẻ đường là gì?',null,'["Là báo hiệu đường bộ để hỗ trợ cảnh báo nguy hiểm cho người tham gia giao thông đường bộ.","Là vạch chỉ sự phân chia làn đường, vị trí hoặc hướng đi, vị trí dừng lại.","Là báo hiệu cho người tham gia giao thông đường bộ về các thông tin của đường bộ.","Cả ba ý trên."]'::jsonb,2,false,'Theo quy chuẩn báo hiệu đường bộ, ''Vạch kẻ đường'' là một dạng báo hiệu để chỉ sự phân chia làn đường, vị trí hoặc hướng đi, vị trí dừng lại của phương tiện tham gia giao thông.'),
(6,1,'Quy định chung và quy tắc giao thông đường bộ','Người điều khiển phương tiện tham gia giao thông đường bộ được hiểu như thế nào là đúng?',null,'["Là người điều khiển xe cơ giới, người điều khiển xe thô sơ, người điều khiển xe máy chuyên dùng.","Là người được giao nhiệm vụ hướng dẫn giao thông trên đường bộ.","Cả hai ý trên."]'::jsonb,1,false,'''Người điều khiển phương tiện tham gia giao thông đường bộ'' bao gồm người điều khiển xe cơ giới, người điều khiển xe thô sơ và người điều khiển xe máy chuyên dùng.'),
(7,1,'Quy định chung và quy tắc giao thông đường bộ','Người lái xe được hiểu như thế nào là đúng?',null,'["Là người điều khiển xe cơ giới.","Là người điều khiển xe thô sơ.","Là người điều khiển xe máy chuyên dùng."]'::jsonb,1,false,'''Người lái xe'' được định nghĩa trong luật là người trực tiếp điều khiển xe cơ giới (như xe ô tô, xe mô tô, xe máy...).'),
(8,1,'Quy định chung và quy tắc giao thông đường bộ','Trong nhóm các phương tiện giao thông đường bộ dưới đây, nhóm phương tiện nào là xe cơ giới?',null,'["Xe ô tô; máy kéo; xe mô tô hai bánh; xe mô tô ba bánh; xe gắn máy; xe cơ giới dùng cho người khuyết tật và xe máy chuyên dùng; xe đạp, xe đạp máy, xe đạp điện.","Xe ô tô; rơ moóc được kéo bởi xe ô tô; sơ mi rơ moóc được kéo bởi ô tô đầu kéo; xe chở người bốn bánh có gắn động cơ; xe chở hàng bốn bánh có gắn động cơ; xe mô tô, xe gắn máy và các loại xe tương tự."]'::jsonb,2,false,'Xe cơ giới gồm: xe ô tô, rơ moóc được kéo bởi ô tô, sơ mi rơ moóc kéo bởi ô tô đầu kéo, xe chở người/hàng bốn bánh có gắn động cơ, xe mô tô, xe gắn máy và các xe tương tự. Chú ý: xe đạp, xe đạp điện, xe lăn và xe máy chuyên dùng không thuộc nhóm xe cơ giới.'),
(9,1,'Quy định chung và quy tắc giao thông đường bộ','Trong nhóm các phương tiện giao thông đường bộ dưới đây, nhóm phương tiện nào là xe thô sơ?',null,'["Xe đạp, xe đạp máy, xe đạp điện; xe xích lô; xe lăn dùng cho người khuyết tật; xe vật nuôi kéo và các loại xe tương tự.","Xe đạp (kể cả xe đạp máy, xe đạp điện), xe gắn máy, xe cơ giới dùng cho người khuyết tật và xe máy chuyên dùng.","Xe ô tô, máy kéo, rơ moóc hoặc sơ mi rơ moóc được kéo bởi xe ô tô, máy kéo."]'::jsonb,1,false,'Xe thô sơ bao gồm: xe đạp (kể cả xe đạp máy, xe đạp điện), xe xích lô, xe lăn dùng cho người khuyết tật, xe do súc vật kéo và các loại xe tương tự.'),
(10,1,'Quy định chung và quy tắc giao thông đường bộ','Phương tiện giao thông đường bộ gồm những loại nào?',null,'["Phương tiện giao thông cơ giới đường bộ.","Phương tiện giao thông thô sơ đường bộ, xe máy chuyên dùng và các loại xe tương tự.","Cả hai ý trên."]'::jsonb,3,false,'Phương tiện giao thông đường bộ gồm 2 nhóm chính: Phương tiện giao thông cơ giới đường bộ và Phương tiện giao thông thô sơ đường bộ, xe máy chuyên dùng cùng các loại xe tương tự.'),
(11,1,'Quy định chung và quy tắc giao thông đường bộ','Người tham gia giao thông đường bộ gồm những đối tượng nào?',null,'["Người điều khiển, người được chở trên phương tiện tham gia giao thông đường bộ.","Người điều khiển, dẫn dắt vật nuôi trên đường bộ; người đi bộ trên đường bộ.","Cả hai ý trên."]'::jsonb,3,false,'''Người tham gia giao thông đường bộ'' là khái niệm rộng nhất, bao gồm người điều khiển, người sử dụng phương tiện; người dẫn dắt súc vật; người đi bộ trên đường bộ.'),
(12,1,'Quy định chung và quy tắc giao thông đường bộ','Người điều khiển phương tiện tham gia giao thông đường bộ gồm những đối tượng nào dưới đây?',null,'["Người điều khiển xe cơ giới, người điều khiển xe thô sơ.","Người điều khiển xe máy chuyên dùng.","Cả hai ý trên."]'::jsonb,3,false,'''Người điều khiển phương tiện giao thông'' gồm cả người lái xe cơ giới, xe thô sơ, xe máy chuyên dùng và người dẫn dắt súc vật khi tham gia giao thông.'),
(13,1,'Quy định chung và quy tắc giao thông đường bộ','Người điều khiển giao thông đường bộ được hiểu như thế nào là đúng?',null,'["Là người điều khiển phương tiện tham gia giao thông đường bộ.","Là Cảnh sát giao thông và người được giao nhiệm vụ hướng dẫn giao thông trên đường bộ.","Là người tham gia giao thông đường bộ."]'::jsonb,2,false,'''Người điều khiển giao thông đường bộ'' là Cảnh sát giao thông (CSGT) và người được giao nhiệm vụ hướng dẫn giao thông tại nơi thi công, nơi ùn tắc, bến phà, tại cầu đường bộ đi chung với đường sắt.'),
(14,1,'Quy định chung và quy tắc giao thông đường bộ','Dừng xe được hiểu như thế nào là đúng?',null,'["Là trạng thái đứng yên của xe không giới hạn thời gian để cho người lên, xuống xe, xếp dỡ hàng hóa hoặc thực hiện công việc khác.","Là trạng thái đứng yên tạm thời của xe trong một khoảng thời gian cần thiết đủ để cho người lên xe, xuống xe, xếp dỡ hàng hóa, kiểm tra kỹ thuật xe hoặc hoạt động khác. Khi dừng xe không được tắt máy và không được rời khỏi vị trí lái, trừ trường hợp rời khỏi vị trí lái để đóng, mở cửa xe, xếp dỡ hàng hóa, kiểm tra kỹ thuật xe nhưng phải sử dụng phanh đỗ xe hoặc thực hiện biện pháp an toàn khác.","Là trạng thái đứng yên của xe không giới hạn thời gian giữa 02 lần vận chuyển hàng hóa hoặc hành khách."]'::jsonb,2,false,'''Dừng xe'' là trạng thái đứng yên TẠM THỜI của phương tiện trong một khoảng thời gian cần thiết đủ để cho người lên, xuống xe, xếp dỡ hàng hóa hoặc thực hiện công việc khác (người lái xe không được rời vị trí lái).'),
(15,1,'Quy định chung và quy tắc giao thông đường bộ','Đỗ xe được hiểu như thế nào là đúng?',null,'["Là trạng thái đứng yên của xe có giới hạn thời gian trong một khoảng thời gian cần thiết đủ để cho người lên, xuống xe đó, xếp dỡ hàng hóa hoặc thực hiện công việc khác.","Là trạng thái đứng yên của xe không giới hạn thời gian. Khi đỗ xe, người điều khiển phương tiện tham gia giao thông đường bộ chỉ được rời khỏi xe khi đã sử dụng phanh đỗ xe hoặc thực hiện biện pháp an toàn khác. Xe đỗ trên đoạn đường dốc phải đánh lái về phía lề đường, chèn bánh."]'::jsonb,2,false,'''Đỗ xe'' là trạng thái đứng yên KHÔNG GIỚI HẠN THỜI GIAN của phương tiện giao thông đường bộ (người lái xe có thể rời khỏi phương tiện sau khi đã thực hiện các biện pháp an toàn).'),
(16,1,'Quy định chung và quy tắc giao thông đường bộ','Đường cao tốc được hiểu như thế nào là đúng?',null,'["Là một cấp kỹ thuật của đường bộ, chỉ dành cho một số loại xe cơ giới, xe máy chuyên dùng tham gia giao thông theo quy định của pháp luật. Có dải phân cách phân chia hai chiều xe chạy riêng biệt, không giao nhau cùng mức với một hoặc các đường khác, chỉ cho xe ra, vào ở những điểm nhất định. Có hàng rào bảo vệ, trang thiết bị phục vụ, bảo đảm giao thông liên tục, an toàn, rút ngắn thời gian hành trình.","Là đường nối liền Thủ đô Hà Nội với trung tâm hành chính cấp tỉnh; đường nối liền các trung tâm hành chính cấp tỉnh; đường có vị trí quan trọng đối với sự phát triển kinh tế- xã hội, bảo đảm quốc phòng, an ninh của vùng, khu vực."]'::jsonb,1,false,'''Đường cao tốc'' là cấp kỹ thuật đường bộ đặc biệt: chỉ dành cho một số loại xe cơ giới/chuyên dùng đạt chuẩn tốc độ; có dải phân cách giữa phân chia 2 chiều; hoàn toàn không giao cắt cùng mức; chỉ ra/vào tại các điểm quy định và có trang thiết bị bảo đảm giao thông an toàn liên tục.'),
(17,1,'Quy định chung và quy tắc giao thông đường bộ','Thiết bị an toàn cho trẻ em được hiểu như thế nào là đúng?',null,'["Là thiết bị có đủ khả năng bảo đảm an toàn cho trẻ em ở tư thế ngồi hoặc nằm trên xe ô tô, được thiết kế để giảm nguy cơ chấn thương cho người dùng trong trường hợp xảy ra va chạm hoặc xe ô tô giảm tốc độ đột ngột, bằng cách hạn chế sự di chuyển của cơ thể trẻ em.","Là thiết bị có đủ khả năng bảo đảm an toàn cho trẻ em ở tư thế đứng hoặc nằm trên xe ô tô, được thiết kế để giảm nguy cơ chấn thương cho người dùng trong trường hợp xe ô tô lưu thông bình thường."]'::jsonb,1,true,'🚨 [CÂU ĐIỂM LIỆT] Theo Luật mới, thiết bị an toàn cho trẻ em được định nghĩa là thiết bị bảo đảm an toàn cho trẻ ở tư thế NGỒI hoặc NẰM trên xe ô tô, thiết kế để hạn chế sự di chuyển của cơ thể trẻ, giảm nguy cơ chấn thương khi va chạm hoặc phanh gấp. Trẻ em tuyệt đối không được ở tư thế đứng trên xe.'),
(18,1,'Quy định chung và quy tắc giao thông đường bộ','Theo chức năng phục vụ thì đường bộ được phân loại như thế nào?',null,'["Đường chính, đường nhánh, đường gom, đường bên, đường dành cho giao thông công cộng, đường nội bộ, đường dành riêng cho người đi bộ, người đi xe đạp và các đường khác.","Đường chính, đường nhánh, đường gom, đường dành cho giao thông công cộng, đường nội bộ, đường dành riêng cho người đi bộ, người đi xe đạp và các đường khác.","Đường chính, đường nhánh, đường gom, đường bên, đường dành cho giao thông công cộng, đường dành riêng cho người đi bộ, người đi xe đạp và các đường khác."]'::jsonb,1,true,'🚨 [CÂU ĐIỂM LIỆT] Theo chức năng phục vụ, đường bộ được phân loại đầy đủ gồm: đường chính, đường nhánh, đường gom, đường bên, đường dành cho giao thông công cộng, đường nội bộ, đường dành riêng cho người đi bộ, xe đạp và các đường khác.'),
(19,1,'Quy định chung và quy tắc giao thông đường bộ','Hành vi nào dưới đây bị nghiêm cấm?',null,'["Sử dụng xe đạp đi trên các tuyến quốc lộ.","Rải vật sắc nhọn, đổ chất gây trơn trượt trên đường bộ.","Cả hai ý trên."]'::jsonb,2,true,'🚨 [CÂU ĐIỂM LIỆT] Hành vi rải vật sắc nhọn (đinh, chông), đổ dầu nhớt hoặc các chất gây trơn trượt trên đường bộ là hành vi phá hoại đặc biệt nguy hiểm, trực tiếp đe dọa tính mạng người tham gia giao thông nên bị nghiêm cấm triệt để và có thể bị truy cứu trách nhiệm hình sự.'),
(20,1,'Quy định chung và quy tắc giao thông đường bộ','Hành vi đưa xe cơ giới, xe máy chuyên dùng tham gia giao thông đường bộ nào dưới đây bị cấm?',null,'["Không có chứng nhận kiểm định an toàn kỹ thuật và bảo vệ môi trường.","Hết niên hạn sử dụng.","Cả hai ý trên."]'::jsonb,3,true,'🚨 [CÂU ĐIỂM LIỆT] Nghiêm cấm đưa phương tiện không có chứng nhận đăng kiểm an toàn kỹ thuật & bảo vệ môi trường, hoặc xe đã hết niên hạn sử dụng tham gia giao thông vì nguy cơ hỏng hóc kỹ thuật (mất phanh, gãy trục...) gây tai nạn thảm khốc.'),
(21,1,'Quy định chung và quy tắc giao thông đường bộ','Tổ chức đua xe được phép thực hiện khi nào?',null,'["Trên đường phố không có người qua lại.","Được người dân ủng hộ.","Được cơ quan có thẩm quyền cấp phép."]'::jsonb,3,true,'🚨 [CÂU ĐIỂM LIỆT] Hoạt động tổ chức đua xe chỉ được phép thực hiện khi có sự chấp thuận và cấp phép chính thức từ cơ quan nhà nước có thẩm quyền trên các cung đường, trường đua được bảo vệ an toàn.'),
(22,1,'Quy định chung và quy tắc giao thông đường bộ','Hành vi đua xe trái phép bị xử lý như thế nào?',null,'["Chỉ bị nhắc nhở.","Tùy theo mức độ của hành vi vi phạm có thể bị xử lý hành chính hoặc xử lý hình sự."]'::jsonb,2,true,'🚨 [CÂU ĐIỂM LIỆT] Đua xe trái phép là hành vi gây nguy hiểm đặc biệt cho xã hội; tùy theo tính chất và mức độ vi phạm sẽ bị xử phạt vi phạm hành chính nặng hoặc bị truy cứu trách nhiệm hình sự (khởi tố tù giam).'),
(23,1,'Quy định chung và quy tắc giao thông đường bộ','Hành vi của người điều khiển xe ô tô và các loại xe tương tự khi tham gia giao thông đường bộ mà trong cơ thể có chất ma túy thì bị áp dụng hình thức xử phạt vi phạm hành chính nào dưới đây?',null,'["Bị phạt tiền.","Bị tước giấy phép lái xe.","Cả hai ý trên."]'::jsonb,3,true,'🚨 [CÂU ĐIỂM LIỆT] Sử dụng ma túy khi điều khiển phương tiện làm tê liệt hệ thần kinh, mất hoàn toàn nhận thức và phản xạ lái xe. Người vi phạm sẽ bị phạt tiền ở khung kịch khung và bị tước quyền sử dụng Giấy phép lái xe.'),
(24,1,'Quy định chung và quy tắc giao thông đường bộ','Người điều khiển phương tiện tham gia giao thông đường bộ mà trong máu hoặc hơi thở có nồng độ cồn có bị nghiêm cấm không?',null,'["Bị nghiêm cấm.","Không bị nghiêm cấm.","Không bị nghiêm cấm, nếu nồng độ cồn trong máu ở mức nhẹ, có thể điều khiển phương tiện tham gia giao thông."]'::jsonb,1,true,'🚨 [CÂU ĐIỂM LIỆT] Luật quy định cấm tuyệt đối hành vi điều khiển phương tiện tham gia giao thông đường bộ mà trong máu hoặc hơi thở có nồng độ cồn (''Đã uống rượu bia - Không lái xe''). Không có mức dung sai nồng độ cồn tối thiểu.'),
(25,1,'Quy định chung và quy tắc giao thông đường bộ','Hành vi của người điều khiển xe ô tô và các loại xe tương tự khi tham gia giao thông đường bộ mà trong máu hoặc hơi thở có nồng độ cồn thì bị áp dụng hình thức xử phạt vi phạm hành chính nào dưới đây?',null,'["Bị phạt tiền.","Có thể bị tước giấy phép lái xe.","Cả hai ý trên."]'::jsonb,3,true,'🚨 [CÂU ĐIỂM LIỆT] Người lái ô tô vi phạm nồng độ cồn sẽ bị áp dụng đồng thời cả hai hình thức: Bị phạt tiền nặng và bị tước giấy phép lái xe theo Nghị định xử phạt của Chính phủ.'),
(26,1,'Quy định chung và quy tắc giao thông đường bộ','Theo Luật Phòng chống tác hại của rượu, bia, đối tượng nào dưới đây bị cấm sử dụng rượu, bia khi tham gia giao thông?',null,'["Người điều khiển xe ô tô, xe mô tô, xe đạp, xe gắn máy.","Người được chở trên xe cơ giới.","Cả hai ý trên."]'::jsonb,1,true,'🚨 [CÂU ĐIỂM LIỆT] Theo Luật Phòng chống tác hại của rượu, bia, cấm tuyệt đối NGƯỜI ĐIỀU KHIỂN phương tiện giao thông (gồm cả ô tô, mô tô, xe gắn máy, xe đạp) sử dụng rượu bia khi tham gia giao thông. Người ngồi sau xe hoặc hành khách không trực tiếp điều khiển thì không thuộc nhóm bị cấm này.'),
(27,1,'Quy định chung và quy tắc giao thông đường bộ','Hành vi giao xe ô tô, mô tô cho người nào sau đây tham gia giao thông đường bộ bị nghiêm cấm?',null,'["Người chưa đủ tuổi theo quy định.","Người không có giấy phép lái xe.","Người có giấy phép lái xe nhưng đã bị trừ hết 12 điểm.","Cả ba ý trên."]'::jsonb,4,true,'🚨 [CÂU ĐIỂM LIỆT] Chủ phương tiện tuyệt đối không được giao xe cho người chưa đủ tuổi, người không có GPLX, hoặc người có GPLX nhưng đã bị trừ hết 12 điểm. Nếu giao xe mà người đó gây tai nạn nghiêm trọng, chủ xe có thể bị xử lý hình sự về tội ''Giao cho người không đủ điều kiện điều khiển phương tiện''.'),
(28,1,'Quy định chung và quy tắc giao thông đường bộ','Hành vi nào sau đây bị nghiêm cấm?',null,'["Điều khiển xe cơ giới lạng lách, đánh võng, rú ga liên tục khi tham gia giao thông trên đường.","Xúc phạm, đe dọa, cản trở, chống đối hoặc không chấp hành hiệu lệnh, hướng dẫn, yêu cầu kiểm tra, kiểm soát của người thi hành công vụ về bảo đảm trật tự, an toàn giao thông đường bộ.","Cả hai ý trên."]'::jsonb,3,true,'🚨 [CÂU ĐIỂM LIỆT] Nghiêm cấm mọi hành vi lạng lách, đánh võng, rú ga liên tục cũng như hành vi xúc phạm, đe dọa, cản trở hoặc chống người thi hành công vụ kiểm soát trật tự an toàn giao thông.'),
(29,1,'Quy định chung và quy tắc giao thông đường bộ','Các hành vi nào sau đây bị cấm đối với phương tiện tham gia giao thông đường bộ?',null,'["Cải tạo xe ô tô loại khác thành xe ô tô chở người phục vụ mục đích quốc phòng, an ninh.","Cải tạo trái phép; cố ý can thiệp làm sai lệch chỉ số trên đồng hồ báo quãng đường đã chạy của xe ô tô; cắt, hàn, tẩy xóa, đục sửa, đóng lại trái phép số khung, số động cơ của xe cơ giới, xe máy chuyên dùng."]'::jsonb,2,true,'🚨 [CÂU ĐIỂM LIỆT] Nghiêm cấm cải tạo xe trái phép, cố ý can thiệp tua đồng hồ công-tơ-mét (quãng đường đã chạy) hoặc tẩy xóa, đục sửa, đóng lại số khung, số động cơ trái quy định của pháp luật.'),
(30,1,'Quy định chung và quy tắc giao thông đường bộ','Hành vi nào sau đây bị cấm?',null,'["Lắp đặt, sử dụng thiết bị âm thanh, ánh sáng trên xe cơ giới, xe máy chuyên dùng gây mất trật tự, an toàn giao thông đường bộ.","Cản trở người, phương tiện tham gia giao thông trên đường bộ; ném gạch, đất, đá, cát hoặc vật thể khác vào người, phương tiện đang tham gia giao thông trên đường bộ.","Cả hai ý trên."]'::jsonb,3,true,'🚨 [CÂU ĐIỂM LIỆT] Bị nghiêm cấm: tự ý lắp đặt còi/đèn ưu tiên, đèn led pha siêu sáng gây mất an toàn giao thông; cản trở giao thông hoặc ném gạch đá, vật lạ vào phương tiện đang lưu thông trên đường.'),
(31,1,'Quy định chung và quy tắc giao thông đường bộ','Việc sản xuất, sử dụng, mua, bán trái phép biển số xe có bị nghiêm cấm hay không?',null,'["Không bị nghiêm cấm.","Bị nghiêm cấm.","Bị nghiêm cấm tuỳ trường hợp."]'::jsonb,2,true,'🚨 [CÂU ĐIỂM LIỆT] Biển số xe do cơ quan công an có thẩm quyền cấp và quản lý. Mọi hành vi tự ý sản xuất, mua bán, sử dụng biển số giả hoặc sửa đổi chữ số đều là hành vi vi phạm pháp luật và bị nghiêm cấm.'),
(32,1,'Quy định chung và quy tắc giao thông đường bộ','Khi điều khiển phương tiện tham gia giao thông, những hành vi nào dưới đây bị nghiêm cấm?',null,'["Thay đổi tốc độ của xe nhiều lần.","Điều khiển phương tiện sau 23 giờ trong ngày.","Lạng lách, đánh võng, rú ga liên tục."]'::jsonb,3,true,'🚨 [CÂU ĐIỂM LIỆT] Khi điều khiển phương tiện, hành vi lạng lách, đánh võng, rú ga bóp còi liên tục gây hoảng loạn cho người đi đường, nguy cơ cao dẫn đến tai nạn nên bị pháp luật nghiêm cấm.'),
(33,1,'Quy định chung và quy tắc giao thông đường bộ','Có bao nhiêu nhóm biển báo hiệu đường bộ?',null,'["Ba nhóm: Biển báo cấm, biển báo nguy hiểm và biển hiệu lệnh.","Bốn nhóm: Biển báo cấm, biển báo nguy hiểm, biển hiệu lệnh và biển phụ.","Năm nhóm: Biển báo cấm, biển báo nguy hiểm, biển hiệu lệnh, biển chỉ dẫn, biển phụ."]'::jsonb,3,false,'Hệ thống báo hiệu đường bộ Việt Nam gồm 5 nhóm chính: 1. Biển báo cấm; 2. Biển báo nguy hiểm và cảnh báo; 3. Biển hiệu lệnh; 4. Biển chỉ dẫn; 5. Biển phụ, biển viết bằng chữ.'),
(34,1,'Quy định chung và quy tắc giao thông đường bộ','Tại nơi có vạch kẻ đường hoặc tại nơi mà người đi bộ, xe lăn của người khuyết tật đang qua đường, người điều khiển phương tiện tham gia giao thông phải thực hiện như thế nào?',null,'["Giảm tốc độ và nhường đường cho người đi bộ, xe lăn của người khuyết tật qua đường đảm bảo an toàn.","Quan sát, giảm tốc độ hoặc dừng lại để bảo đảm an toàn cho người đi bộ, xe lăn của người khuyết tật qua đường.","Quan sát, tăng tốc độ và điều khiển phương tiện nhanh chóng đi qua."]'::jsonb,2,false,'Khi đến nơi có vạch kẻ đường cho người đi bộ qua đường hoặc khi thấy người đi bộ, người khuyết tật dùng xe lăn đang qua đường, người lái xe phải quan sát, giảm tốc độ hoặc dừng lại để nhường đường an toàn.'),
(35,1,'Quy định chung và quy tắc giao thông đường bộ','Người điều khiển xe mô tô phải phải quan sát, giảm tốc độ hoặc dừng lại để bảo đảm an toàn trong các trường hợp nào dưới đây?',null,'["Đường hẹp, đường vòng, đường quanh co, đường đèo, dốc.","Nơi cầu, cống hẹp, đập tràn, đường ngầm, hầm chui, hầm đường bộ.","Trời mưa, gió, sương, khói, bụi, mặt đường trơn trượt, lầy lội, có nhiều đất đá, vật liệu rơi vãi ảnh hưởng đến an toàn giao thông đường bộ.","Cả ba ý trên."]'::jsonb,4,true,'🚨 [CÂU ĐIỂM LIỆT] Người lái xe mô tô, ô tô bắt buộc phải quan sát, giảm tốc độ hoặc dừng lại nhường đường khi: gặp người đi bộ qua đường; gặp xe buýt đang dừng đón trả khách; hoặc tại nơi giao nhau không có báo hiệu đi theo vòng xuyến.'),
(36,1,'Quy định chung và quy tắc giao thông đường bộ','Khi gặp hiệu lệnh điều khiển của Cảnh sát giao thông như hình dưới đây thì người tham gia giao thông đường bộ phải đi như thế nào là đúng quy tắc giao thông?','images/cau_36.webp','["Người tham gia giao thông đường bộ ở các hướng phải dừng lại.","Người tham gia giao thông đường bộ ở các hướng được đi theo chiều gậy chỉ của Cảnh sát giao thông.","Người tham gia giao thông đường bộ ở phía trước và phía sau người điều khiển được đi tất cả các hướng; người tham gia giao thông đường bộ ở phía bên phải và phía bên trái người điều khiển phải dừng lại.","Người tham gia giao thông đường bộ ở phía trước và phía sau người điều khiển phải dừng lại; người tham gia giao thông đường bộ ở phía bên phải và phía bên trái người điều khiển được đi tất cả các hướng."]'::jsonb,4,false,'Hiệu lệnh CSGT giang hai tay hoặc một tay sang ngang: Người tham gia giao thông ở phía trước và phía sau người chỉ huy phải DỪNG LẠI; người tham gia giao thông ở phía bên phải và bên trái được ĐI TẤT CẢ CÁC HƯỚNG.'),
(37,1,'Quy định chung và quy tắc giao thông đường bộ','Khi gặp hiệu lệnh điều khiển của Cảnh sát giao thông như hình dưới đây thì người tham gia giao thông đường bộ phải đi như thế nào là đúng quy tắc giao thông?','images/cau_37.webp','["Người tham gia giao thông đường bộ ở phía sau Cảnh sát giao thông được đi, các hướng khác phải dừng lại.","Người tham gia giao thông đường bộ được rẽ phải theo chiều mũi tên màu xanh ở bục Cảnh sát giao thông.","Người tham gia giao thông đường bộ ở tất cả các hướng phải dừng lại, trừ các xe đã ở trong khu vực giao nhau.","Người tham gia giao thông đường bộ ở phía trước Cảnh sát giao thông phải dừng lại, các hướng khác được đi."]'::jsonb,3,false,'Hiệu lệnh CSGT giơ tay thẳng đứng: Người tham gia giao thông ở TẤT CẢ CÁC HƯỚNG đều phải dừng lại (trừ các xe đã ở trong khu vực giao nhau thì được tiếp tục đi).'),
(38,1,'Quy định chung và quy tắc giao thông đường bộ','Khi hiệu lệnh của người điều khiển giao thông trái với tín hiệu đèn giao thông hoặc biển báo hiệu đường bộ thì người tham gia giao thông đường bộ phải chấp hành báo hiệu đường bộ nào dưới đây?',null,'["Theo hiệu lệnh của người điều khiển giao thông.","Theo tín hiệu đèn giao thông.","Theo biển báo hiệu đường bộ."]'::jsonb,1,false,'Thứ tự ưu tiên hiệu lực của báo hiệu giao thông: 1. Hiệu lệnh của người điều khiển giao thông (CSGT) là cao nhất; 2. Tín hiệu đèn; 3. Biển báo hiệu; 4. Vạch kẻ đường. Do đó phải chấp hành hiệu lệnh của CSGT trước.'),
(39,1,'Quy định chung và quy tắc giao thông đường bộ','Khi ở một vị trí vừa có biển báo hiệu đặt cố định vừa có biển báo hiệu tạm thời mà hai biển có ý nghĩa khác nhau, người tham gia giao thông đường bộ phải chấp hành hiệu lệnh của biển báo hiệu nào?',null,'["Biển báo hiệu đặt cố định.","Biển báo hiệu tạm thời.","Theo quyết định của người tham gia giao thông nhưng phải bảo đảm an toàn."]'::jsonb,2,false,'Khi tại một khu vực đồng thời có biển báo cố định và biển báo tạm thời (như khu vực công trường, sửa chữa đường) mà ý nghĩa khác nhau, người tham gia giao thông phải chấp hành theo hiệu lệnh của BIỂN BÁO HIỆU TẠM THỜI.'),
(40,1,'Quy định chung và quy tắc giao thông đường bộ','Tại nơi đường giao nhau, khi đèn điều khiển giao thông có tín hiệu màu vàng, người điều khiển phương tiện tham gia giao thông phải chấp hành như thế nào là đúng quy tắc giao thông?',null,'["Dừng lại trước vạch dừng; trường hợp đang đi trên vạch dừng hoặc đã đi qua vạch dừng mà tín hiệu đèn màu vàng thì được đi tiếp; trường hợp tín hiệu đèn màu vàng nhấp nháy, người điều khiển phương tiện tham gia giao thông đường bộ được đi nhưng phải quan sát, giảm tốc độ hoặc dừng lại nhường đường cho người đi bộ, xe lăn của người khuyết tật qua đường hoặc các phương tiện khác.","Tăng tốc độ nhanh chóng vượt qua nút giao.","Quan sát, giảm tốc độ, từ từ vượt qua nút giao."]'::jsonb,1,false,'Khi gặp tín hiệu đèn vàng: Người lái xe phải dừng lại trước vạch dừng. Trường hợp đã đi quá vạch dừng hoặc đã quá gần vạch dừng mà dừng lại sẽ gây nguy hiểm thì được phép tiếp tục đi tiếp.'),
(41,1,'Quy định chung và quy tắc giao thông đường bộ','Người lái xe trên đường cần chấp hành quy định về tốc độ tối đa như thế nào?',null,'["Chỉ lớn hơn tốc độ tối đa cho phép khi đường vắng.","Chỉ lớn hơn tốc độ tối đa cho phép khi vào ban đêm.","Không vượt quá tốc độ tối đa cho phép."]'::jsonb,3,false,'Người lái xe khi tham gia giao thông trên đường bộ phải chấp hành nghiêm túc quy định về tốc độ, luôn làm chủ tốc độ và TUYỆT ĐỐI KHÔNG ĐƯỢC VƯỢT QUÁ tốc độ tối đa cho phép trên tuyến đường đó.'),
(42,1,'Quy định chung và quy tắc giao thông đường bộ','Khi chở trẻ em dưới 10 tuổi và chiều cao dưới 1,35 mét trên xe ô tô, người lái xe phải thực hiện quy tắc nào dưới đây để bảo đảm an toàn?',null,'["Không được cho trẻ em ngồi cùng hàng ghế với người lái xe, trừ loại xe ô tô chỉ có một hàng ghế; người lái xe phải sử dụng, hướng dẫn sử dụng thiết bị an toàn phù hợp cho trẻ em.","Cho trẻ em ngồi cùng hàng ghế với người lái xe, người lái xe phải sử dụng, hướng dẫn sử dụng thiết bị an toàn phù hợp cho trẻ em."]'::jsonb,1,false,'Luật Trật tự, ATGT đường bộ quy định: Khi chở trẻ em dưới 10 tuổi và chiều cao dưới 1,35 mét trên xe ô tô con, KHÔNG ĐƯỢC cho trẻ ngồi cùng hàng ghế với người lái xe (trừ loại xe chỉ có một hàng ghế); đồng thời phải sử dụng thiết bị an toàn phù hợp.'),
(43,1,'Quy định chung và quy tắc giao thông đường bộ','Phương tiện tham gia giao thông đường bộ di chuyển với tốc độ thấp hơn phải đi như thế nào?',null,'["Đi về bên trái theo chiều đi của mình.","Đi về bên phải theo chiều đi của mình.","Đi ở bất cứ bên nào nhưng phải bấm đèn cảnh báo nguy hiểm để báo hiệu cho các phương tiện khác."]'::jsonb,2,false,'Quy tắc cơ bản khi tham gia giao thông: Phương tiện di chuyển với tốc độ THẤP HƠN phải đi về phía bên PHẢI theo chiều đi của mình để không cản trở các xe di chuyển nhanh hơn.'),
(44,1,'Quy định chung và quy tắc giao thông đường bộ','Trên một chiều đường có vạch kẻ phân làn đường, người lái xe cơ giới, xe máy chuyên dùng phải điều khiển xe đi trên làn đường nào?',null,'["Đi trên làn đường bên phải trong cùng.","Đi trên làn đường bên trái.","Đi ở bất cứ làn nào nhưng phải bảo đảm tốc độ cho phép."]'::jsonb,2,false,'Trên đường một chiều có nhiều làn phân cách bằng vạch kẻ, làn đường bên trái ngoài cùng thường dành cho xe cơ giới di chuyển nhanh; các phương tiện thô sơ và xe di chuyển chậm phải đi trên các làn phía bên phải.'),
(45,1,'Quy định chung và quy tắc giao thông đường bộ','Người lái xe phải giảm tốc độ, có tín hiệu rẽ phải và đi sát về bên phải của phần đường xe chạy trong các trường hợp nào dưới đây?',null,'["Khi xe chạy phía trước có tín hiệu vượt xe khác.","Khi phía trước có xe chạy ngược chiều.","Khi xe sau xin vượt nếu đủ điều kiện an toàn.","Khi xe sau có tín hiệu vượt bên phải."]'::jsonb,3,true,'🚨 [CÂU ĐIỂM LIỆT] Khi xe sau xin vượt, nếu đủ điều kiện an toàn, người lái xe phía trước phải giảm tốc độ, bật đèn xi-nhan rẽ phải và đi sát về lề bên phải để nhường đường. Tuyệt đối không được tăng tốc hay gây cản trở xe sau vượt.'),
(46,1,'Quy định chung và quy tắc giao thông đường bộ','Vượt xe là gì?',null,'["Là tình huống giao thông trên đường mà mỗi chiều đường xe chạy chỉ có một làn đường dành cho xe cơ giới, xe đi phía sau di chuyển sang bên trái để di chuyển lên trước xe phía trước.","Là tình huống giao thông trên đường có từ hai làn đường dành cho xe cơ giới cùng chiều trở lên được phân biệt bằng vạch kẻ đường, xe đi phía sau di chuyển lên trước xe phía trước theo quy tắc sử dụng làn đường."]'::jsonb,1,false,'Khái niệm ''Vượt xe'': Là tình huống giao thông trên đường mà mỗi chiều đường chỉ có một làn xe cơ giới, xe phía sau muốn đi lên trước phải mượn phần đường hoặc làn đường bên trái của xe trước để vượt qua.'),
(47,1,'Quy định chung và quy tắc giao thông đường bộ','Người lái xe được phép vượt xe trên cầu hẹp có một làn đường, đường cong có tầm nhìn bị hạn chế hay không?',null,'["Được phép vượt khi đường vắng.","Không được phép vượt.","Được phép vượt khi có việc gấp."]'::jsonb,2,true,'🚨 [CÂU ĐIỂM LIỆT] Cầu hẹp một làn xe và khúc cua khuất tầm nhìn là những vị trí tiềm ẩn nguy cơ đối đầu trực diện với xe ngược chiều vô cùng nguy hiểm. Pháp luật NGHIÊM CẤM vượt xe trong mọi trường hợp tại các vị trí này.'),
(48,1,'Quy định chung và quy tắc giao thông đường bộ','Muốn vượt xe phía trước, người lái xe mô tô phải có tín hiệu như thế nào dưới đây để bảo đảm an toàn?',null,'["Bấm còi liên tục để xe phía trước biết xe mình xin vượt.","Rú ga liên tục để xe phía trước biết xe mình xin vượt.","Báo hiệu nhấp nháy bằng đèn chiếu sáng phía trước hoặc còi."]'::jsonb,3,false,'Khi muốn vượt xe, người lái xe mô tô phải có tín hiệu báo hiệu nhấp nháy bằng đèn chiếu sáng phía trước hoặc bằng còi. Tuyệt đối không rú ga, nẹt pô hay bấm còi dồn dập gây hoảng loạn.'),
(49,1,'Quy định chung và quy tắc giao thông đường bộ','Khi lái xe trong khu đông dân cư, khu vực cơ sở khám bệnh, chữa bệnh trừ các khu vực có biển cấm sử dụng còi, người lái xe được sử dụng còi trong thời gian nào?',null,'["Từ 22 giờ ngày hôm trước đến 05 giờ ngày hôm sau.","Từ 05 giờ đến 22 giờ.","Từ 23 giờ ngày hôm trước đến 05 giờ sáng hôm sau."]'::jsonb,2,false,'Trong khu đông dân cư và khu vực bệnh viện, chỉ được phép sử dụng còi trong khung giờ ban ngày từ 05 giờ sáng đến 22 giờ đêm nhằm bảo đảm sự yên tĩnh và nghỉ ngơi của người dân.'),
(50,1,'Quy định chung và quy tắc giao thông đường bộ','Phương tiện tham gia giao thông đường bộ chỉ được sử dụng tín hiệu còi trong các trường hợp nào sau đây?',null,'["Để báo hiệu cho người tham gia giao thông đường bộ khi xuất hiện tình huống có thể mất an toàn giao thông hoặc báo hiệu chuẩn bị vượt xe.","Để báo hiệu cho người tham gia giao thông đường bộ từ 22 giờ ngày hôm trước đến 05 giờ ngày hôm sau trong khu đông dân cư, khu vực cơ sở khám bệnh, chữa bệnh, trừ xe ưu tiên.","Cả hai ý trên."]'::jsonb,1,false,'Tín hiệu còi chỉ được dùng để báo hiệu khi có nguy cơ mất an toàn hoặc báo hiệu xin vượt xe. Từ 22h đêm đến 5h sáng hôm sau trong đô thị, phải dùng đèn pha/cos nhấp nháy thay cho còi.'),
(51,1,'Quy định chung và quy tắc giao thông đường bộ','Người lái xe sử dụng đèn như thế nào khi đi trên các đoạn đường qua khu đông dân cư có hệ thống chiếu sáng đang hoạt động?',null,'["Chỉ bật đèn chiếu xa (đèn pha).","Bật đèn chiếu xa (đèn pha) khi đường vắng, bật đèn chiếu gần (đèn cốt) khi có xe đi ngược chiều.","Chỉ bật đèn chiếu gần (đèn cốt)."]'::jsonb,3,false,'Khi lưu thông trong khu đông dân cư có đèn đường vào ban đêm, người lái xe CHỈ ĐƯỢC BẬT ĐÈN CHIẾU GẦN (đèn cốt). Cấm bật đèn chiếu xa (đèn pha) vì sẽ làm lóa mắt các phương tiện đi ngược chiều và phía trước.'),
(52,1,'Quy định chung và quy tắc giao thông đường bộ','Khi điều khiển phương tiện tham gia giao thông, hành vi nào sau đây bị cấm?',null,'["Dùng tay cầm và sử dụng điện thoại hoặc thiết bị điện tử khác.","Chỉ được chở người trên thùng xe ô tô chở hàng trong trường hợp chở người đi làm nhiệm vụ cứu nạn, cứu hộ, phòng, chống thiên tai, dịch bệnh hoặc thực hiện nhiệm vụ khẩn cấp."]'::jsonb,1,true,'🚨 [CÂU ĐIỂM LIỆT] Dùng tay cầm và sử dụng điện thoại, thiết bị điện tử khi đang lái xe làm phân tâm thị giác, giảm 80% khả năng phản xạ xử lý tình huống khẩn cấp, là nguyên nhân hàng đầu gây tai nạn nên bị nghiêm cấm triệt để.'),
(53,1,'Quy định chung và quy tắc giao thông đường bộ','Người lái xe không được vượt xe khác khi gặp trường hợp nào dưới đây?',null,'["Trên cầu hẹp có một làn đường; nơi đường giao nhau, đường bộ giao nhau cùng mức với đường sắt; khi gặp xe ưu tiên.","Trên cầu có từ 02 làn xe trở lên.","Trên đường có 02 làn đường được phân chia làn bằng vạch kẻ nét đứt."]'::jsonb,1,false,'Không được vượt xe khác khi: đi trên cầu hẹp một làn xe, nơi đường giao nhau, đường bộ giao cắt đường sắt, khi tầm nhìn bị che khuất, hoặc khi có xe ưu tiên đang phát tín hiệu làm nhiệm vụ.'),
(54,1,'Quy định chung và quy tắc giao thông đường bộ','Nơi nào cấm quay đầu xe?',null,'["Ở phần đường dành cho người đi bộ qua đường, trên cầu, đầu cầu, gầm cầu vượt, ngầm.","Tại nơi đường bộ giao nhau cùng mức với đường sắt, đường hẹp, đường dốc, đoạn đường cong tầm nhìn bị che khuất, trên đường cao tốc, trong hầm đường bộ, trên đường một chiều.","Cả hai ý trên."]'::jsonb,3,true,'🚨 [CÂU ĐIỂM LIỆT] Nghiêm cấm quay đầu xe tại các vị trí: phần đường người đi bộ, trên cầu, đầu cầu, gầm cầu vượt, ngầm, đường sắt giao nhau, đường dốc, đường hẹp, đường cong khuất tầm nhìn, trong hầm và trên đường cao tốc.'),
(55,1,'Quy định chung và quy tắc giao thông đường bộ','Người lái xe không được quay đầu xe trong các trường hợp nào dưới đây?',null,'["Ở phần đường dành cho người đi bộ qua đường, trên cầu, đầu cầu, trên đường cao tốc, tại nơi đường bộ giao nhau cùng mức với đường sắt, đường hẹp, đường dốc.","Ở phía trước hoặc phía sau của phần đường dành cho người đi bộ qua đường, trên đường quốc lộ.","Cả hai ý trên."]'::jsonb,1,true,'🚨 [CÂU ĐIỂM LIỆT] Người lái xe không được phép quay đầu xe ở phần đường người đi bộ qua đường, trên cầu, đầu cầu, trên đường cao tốc, nơi giao cắt với đường sắt, đoạn đường cong hay đường dốc vì nguy cơ xung đột luồng xe cực lớn.'),
(56,1,'Quy định chung và quy tắc giao thông đường bộ','Trước khi cho xe chuyển hướng, người lái xe phải làm gì để bảo đảm an toàn giao thông?',null,'["Phải quan sát, bảo đảm khoảng cách an toàn với xe phía sau.","Giảm tốc độ và có tín hiệu báo hướng rẽ.","Chuyển dần sang làn gần nhất với hướng rẽ. Khi bảo đảm an toàn, không gây trở ngại cho người và phương tiện khác mới được chuyển hướng.","Cả ba ý trên."]'::jsonb,4,false,'Trước khi chuyển hướng, người lái xe phải thực hiện đầy đủ: 1. Quan sát an toàn gương chiếu hậu; 2. Giảm tốc độ và bật xi-nhan báo rẽ; 3. Chuyển dần sang làn đường thích hợp khi bảo đảm không gây trở ngại.'),
(57,1,'Quy định chung và quy tắc giao thông đường bộ','Khi chuyển làn đường, người lái xe phải bật đèn tín hiệu báo rẽ như thế nào là đúng quy tắc giao thông?',null,'["Khi bắt đầu chuyển làn đường.","Trước khi thay đổi làn đường.","Sau khi thay đổi làn đường."]'::jsonb,2,false,'Quy tắc an toàn khi chuyển làn: Người lái xe phải bật đèn tín hiệu báo rẽ (xi-nhan) TRƯỚC KHI thay đổi làn đường một khoảng cách an toàn để các xe phía sau kịp thời nhận biết và chủ động nhường đường.'),
(58,1,'Quy định chung và quy tắc giao thông đường bộ','Người lái xe không được lùi xe ở những khu vực nào dưới đây?',null,'["Ở đường một chiều, khu vực cấm dừng, trên phần đường dành cho người đi bộ qua đường.","Nơi đường bộ giao nhau, đường bộ giao nhau cùng mức với đường sắt.","Nơi tầm nhìn bị che khuất, trong hầm đường bộ, trên đường cao tốc.","Cả ba ý trên."]'::jsonb,4,true,'🚨 [CÂU ĐIỂM LIỆT] Cấm lùi xe ở: đường một chiều, khu vực cấm dừng đỗ, phần đường người đi bộ, nơi giao nhau, nơi giao cắt đường sắt, nơi khuất tầm nhìn, trong hầm đường bộ và đặc biệt trên đường cao tốc.'),
(59,1,'Quy định chung và quy tắc giao thông đường bộ','Người điều khiển phương tiện tham gia giao thông không được dừng xe, đỗ xe ở những vị trí nào sau đây?',null,'["Trên miệng cống thoát nước, miệng hầm của đường điện thoại, điện cao thế, chỗ dành riêng cho xe chữa cháy lấy nước.","Trong phạm vi an toàn của đường sắt.","Cả hai ý trên."]'::jsonb,3,true,'🚨 [CÂU ĐIỂM LIỆT] Cấm dừng xe, đỗ xe trên miệng cống thoát nước, miệng hầm đường dây điện thoại, điện cao thế, trụ nước cứu hỏa và trong phạm vi hành lang an toàn đường sắt để phục vụ thoát nạn và cứu hỏa.'),
(60,1,'Quy định chung và quy tắc giao thông đường bộ','Trên đường phố, người điều khiển phương tiện tham gia giao thông đường bộ được dừng xe, đỗ xe sát theo lề đường, vỉa hè phía bên phải theo chiều đi của mình; bánh xe gần nhất không được cách xa lề đường, vỉa hè không quá bao nhiêu mét trong các trường hợp dưới đây và không gây cản trở, nguy hiểm cho người và phương tiện tham gia giao thông đường bộ?',null,'["0,25 mét.","0,3 mét.","0,4 mét.","0,5 mét."]'::jsonb,1,true,'🚨 [CÂU ĐIỂM LIỆT] Khi dừng xe, đỗ xe trên đường phố sát lề đường/vỉa hè bên phải, khoảng cách từ bánh xe gần nhất đến mép lề đường, hè phố không được vượt quá 0,25 mét để bảo đảm không chiếm dụng lòng đường và cản trở lưu thông.'),
(61,1,'Quy định chung và quy tắc giao thông đường bộ','Khi dừng, đỗ xe trên đường phố hẹp, người lái xe ô tô phải dừng, đỗ xe ở vị trí cách xe ô tô đang đỗ ngược chiều khoảng cách tối thiểu là bao nhiêu mét trong các trường hợp dưới đây để bảo đảm an toàn?',null,'["10 mét.","15 mét.","20 mét.","25 mét."]'::jsonb,3,false,'Khi dừng, đỗ xe trên đường phố hẹp, người lái xe phải đỗ cách xe ô tô đang đỗ ngược chiều tối thiểu 20 mét để bảo đảm có đủ khoảng trống cho các phương tiện khác lưu thông qua lại an toàn, tránh gây ùn tắc giao thông.'),
(62,1,'Quy định chung và quy tắc giao thông đường bộ','Người điều khiển phương tiện tham gia giao thông đường bộ không được dừng xe, đỗ xe tại các vị trí nào sau đây?',null,'["Nơi có lề đường rộng hoặc khu đất ở bên ngoài phần đường xe chạy.","Song song cùng chiều với một xe khác đang dừng, đỗ trên đường; trên đoạn đường cong hoặc gần đầu dốc mà tầm nhìn bị che khuất; bên trái đường một chiều.","Cả hai ý trên."]'::jsonb,2,true,'🚨 [CÂU ĐIỂM LIỆT] Nghiêm cấm dừng đỗ song song với xe khác đang đỗ, đỗ ở đoạn đường cong, gần đầu dốc khuất tầm nhìn hoặc bên trái đường một chiều vì sẽ bịt kín làn đường và tiềm ẩn nguy cơ tai nạn đặc biệt nghiêm trọng.'),
(63,1,'Quy định chung và quy tắc giao thông đường bộ','Người điều khiển xe mô tô hai bánh, xe mô tô ba bánh, xe gắn máy có được phép sử dụng xe để kéo hoặc đẩy các phương tiện khác khi tham gia giao thông không?',null,'["Được phép.","Nếu phương tiện được kéo, đẩy có khối lượng nhỏ hơn phương tiện của mình.","Tùy trường hợp.","Không được phép."]'::jsonb,4,true,'🚨 [CÂU ĐIỂM LIỆT] Xe mô tô, xe gắn máy KHÔNG ĐƯỢC PHÉP kéo hoặc đẩy các phương tiện khác, vật khác khi tham gia giao thông. Hành vi này làm mất khả năng giữ thăng bằng và mất lái hoàn toàn.'),
(64,1,'Quy định chung và quy tắc giao thông đường bộ','Khi điều khiển xe mô tô hai bánh, xe mô tô ba bánh, xe gắn máy, những hành vi nào sau đây không được phép?',null,'["Buông cả hai tay; đứng, nằm trên xe điều khiển xe; sử dụng chân chống hoặc vật khác quệt xuống đường khi xe đang chạy.","Chở tối đa hai người phía sau khi chở người bệnh đi cấp cứu, áp giải người có hành vi vi phạm pháp luật, trẻ em dưới 12 tuổi và người già yếu hoặc người khuyết tật."]'::jsonb,1,true,'🚨 [CÂU ĐIỂM LIỆT] Cấm người điều khiển mô tô buông cả hai tay; cấm đứng, nằm trên xe lái xe; cấm dùng chân chống hoặc vật khác quẹt xuống đường tạo tia lửa điện khi xe đang chạy.'),
(65,1,'Quy định chung và quy tắc giao thông đường bộ','Khi điều khiển xe mô tô hai bánh, xe mô tô ba bánh, xe gắn máy, những hành vi nào sau đây không được phép?',null,'["Buông cả hai tay; sử dụng xe để kéo, đẩy xe khác, vật khác; sử dụng chân chống hoặc vật khác quệt xuống đường khi xe đang chạy.","Sử dụng xe để chở người hoặc hàng hóa; để chân chạm xuống đất khi khởi hành.","Đội mũ bảo hiểm; chạy xe đúng tốc độ quy định và chấp hành đúng quy tắc giao thông đường bộ.","Chở người ngồi sau dưới 16 tuổi."]'::jsonb,1,true,'🚨 [CÂU ĐIỂM LIỆT] Người điều khiển mô tô hai bánh, ba bánh, xe gắn máy không được buông cả 2 tay, không được kéo đẩy xe khác, không được quệt chân chống xuống đường khi đang chạy.'),
(66,1,'Quy định chung và quy tắc giao thông đường bộ','Người được chở trên xe mô tô hai bánh, xe mô tô ba bánh, xe gắn máy khi tham gia giao thông đường bộ không được thực hiện hành vi nào sau đây?',null,'["Mang, vác vật cồng kềnh.","Bám, kéo hoặc đẩy các phương tiện khác.","Dùng tay cầm điện thoại hoặc các thiết bị điện tử khác.","Ý 1 và ý 2."]'::jsonb,4,false,'Người được chở trên xe mô tô, xe gắn máy không được mang vác vật cồng kềnh, không được bám, kéo hoặc đẩy các phương tiện khác vì dễ gây mất thăng bằng ngã đổ xe.'),
(67,1,'Quy định chung và quy tắc giao thông đường bộ','Người được chở trên xe mô tô hai bánh, xe mô tô ba bánh, xe gắn máy khi tham gia giao thông đường bộ có được bám, kéo hoặc đẩy các phương tiện khác không?',null,'["Được phép.","Được bám trong trường hợp phương tiện của mình bị hỏng.","Được kéo, đẩy trong trường hợp phương tiện khác bị hỏng.","Không được phép."]'::jsonb,4,false,'Người được chở trên xe mô tô, xe gắn máy tuyệt đối KHÔNG ĐƯỢC PHÉP bám, kéo hoặc đẩy các phương tiện khác dưới bất kỳ hình thức nào.'),
(68,1,'Quy định chung và quy tắc giao thông đường bộ','Người lái xe, người được chở trên xe mô tô hai bánh, xe mô tô ba bánh, xe gắn máy phải thực hiện quy định nào dưới đây?',null,'["Đội mũ bảo hiểm theo đúng quy chuẩn kỹ thuật quốc gia và cài quai đúng quy cách.","Người lái xe phải đội mũ bảo hiểm, người được chở trên xe không nhất thiết phải đội mũ bảo hiểm.","Phải đội mũ bảo hiểm nhưng không nhất thiết phải cài quai."]'::jsonb,1,false,'Người lái xe và người ngồi trên xe mô tô hai bánh, ba bánh, xe gắn máy bắt buộc phải đội mũ bảo hiểm đạt chuẩn chất lượng quốc gia và cài quai đúng quy cách để bảo vệ phần đầu khi có va chạm.'),
(69,1,'Quy định chung và quy tắc giao thông đường bộ','Người lái xe mô tô hai bánh, xe gắn máy được phép chở tối đa hai người trong những trường hợp nào?',null,'["Chở người bệnh đi cấp cứu; áp giải người có hành vi vi phạm pháp luật; trẻ em dưới 12 tuổi; người già yếu hoặc người khuyết tật.","Người đã uống rượu, bia; người trong cơ thể có chất ma tuý.","Cả hai ý trên."]'::jsonb,1,false,'Xe mô tô 2 bánh, xe gắn máy chỉ được chở tối đa 2 người trong 4 trường hợp đặc biệt: 1. Chở người bệnh đi cấp cứu; 2. Áp giải người vi phạm pháp luật; 3. Trẻ em dưới 12 tuổi; 4. Người già yếu hoặc người khuyết tật.'),
(70,1,'Quy định chung và quy tắc giao thông đường bộ','Người lái xe mô tô hai bánh, xe mô tô ba bánh, xe gắn máy không được thực hiện các hành vi nào dưới đây?',null,'["Đi xe dàn hàng ngang; buông cả hai tay.","Sử dụng xe để kéo, đẩy xe khác, vật khác, dẫn dắt vật nuôi, mang, vác và chở vật cồng kềnh; chở người đứng trên xe, giá đèo hàng hoặc ngồi trên tay lái; xếp hàng hóa trên xe quá giới hạn quy định.","Ngồi về một bên điều khiển xe; đứng, nằm trên xe điều khiển xe; thay người lái xe khi xe đang chạy; quay người về phía sau để điều khiển xe hoặc bịt mắt điều khiển xe; sử dụng chân chống hoặc vật khác quệt xuống đường khi xe đang chạy.","Cả ba ý trên."]'::jsonb,4,true,'🚨 [CÂU ĐIỂM LIỆT] Người lái xe mô tô bị nghiêm cấm: đi xe dàn hàng ngang; buông 2 tay; kéo đẩy xe khác; chở người đứng trên xe, giá đèo hàng hoặc ngồi trên tay lái; nằm trên xe lái xe; quẹt chân chống xuống đường.'),
(71,1,'Quy định chung và quy tắc giao thông đường bộ','Người lái xe mô tô hai bánh, xe mô tô ba bánh, xe gắn máy không được thực hiện các hành vi nào sau đây?',null,'["Đi xe dàn hàng ngang; đi xe vào phần đường dành cho người đi bộ và phương tiện khác.","Sử dụng ô, thiết bị âm thanh, trừ thiết bị trợ thính.","Cả hai ý trên."]'::jsonb,3,true,'🚨 [CÂU ĐIỂM LIỆT] Nghiêm cấm lái xe mô tô dàn hàng ngang, đi vào vỉa hè dành cho người đi bộ, sử dụng ô (dù), sử dụng thiết bị âm thanh như tai nghe nhạc (chỉ trừ thiết bị trợ thính y tế).'),
(72,1,'Quy định chung và quy tắc giao thông đường bộ','Người lái xe mô tô hai bánh, xe mô tô ba bánh, xe gắn máy không được thực hiện hành vi nào sau đây?',null,'["Đi trên phần đường, làn đường quy định, chấp hành hiệu lệnh của người điều khiển giao thông, đèn tín hiệu giao thông.","Đi xe dàn hàng ngang, đi xe vào phần đường dành cho người đi bộ.","Cả hai ý trên."]'::jsonb,2,true,'🚨 [CÂU ĐIỂM LIỆT] Người điều khiển xe mô tô không được thực hiện hành vi: đi xe dàn hàng ngang và đi xe vào phần đường dành cho người đi bộ.'),
(73,1,'Quy định chung và quy tắc giao thông đường bộ','Người được chở trên xe mô tô hai bánh, xe mô tô ba bánh, xe gắn máy khi tham gia giao thông đường bộ có được sử dụng ô khi trời mưa hay không?',null,'["Được sử dụng.","Chỉ người ngồi sau được sử dụng.","Không được sử dụng.","Được sử dụng nếu không có áo mưa."]'::jsonb,3,false,'Người ngồi trên xe mô tô, xe gắn máy khi trời mưa KHÔNG ĐƯỢC PHÉP sử dụng ô (dù) vì sức gió cản của ô sẽ làm lật đổ xe, gây nguy hiểm cho bản thân và người xung quanh.'),
(74,1,'Quy định chung và quy tắc giao thông đường bộ','Người được chở trên xe mô tô có được kéo theo người đang điều khiển xe đạp hay không?',null,'["Chỉ được phép nếu cả hai đội mũ bảo hiểm.","Không được phép.","Chỉ được thực hiện trên đường vắng."]'::jsonb,2,true,'🚨 [CÂU ĐIỂM LIỆT] Người ngồi trên mô tô KHÔNG ĐƯỢC PHÉP kéo theo người đang đi xe đạp vì rất dễ làm xe đạp mất lái, ngã cuốn vào gầm xe khác.'),
(75,1,'Quy định chung và quy tắc giao thông đường bộ','Trường hợp người được chở trên xe mô tô, xe gắn máy, các loại xe tương tự xe mô tô và các loại xe tương tự xe gắn máy không đội "mũ bảo hiểm cho người đi mô tô, xe máy" hoặc không cài quai đúng quy cách (trừ trường hợp chở người bệnh đi cấp cứu, trẻ em dưới 06 tuổi, áp giải người có hành vi vi phạm pháp luật) thì việc xử phạt vi phạm hành chính được quy định như thế nào?',null,'["Không bị xử phạt chỉ bị nhắc nhở.","Người được chở không bị xử phạt, chỉ xử phạt người điều khiển xe mô tô, xe gắn máy.","Người được chở bị xử phạt, không xử phạt người điều khiển xe mô tô, xe gắn máy.","Xử phạt cả người điều khiển và người được chở trên xe mô tô, xe gắn máy."]'::jsonb,4,true,'🚨 [CÂU ĐIỂM LIỆT] Pháp luật quy định xử phạt vi phạm hành chính đối với CẢ NGƯỜI ĐIỀU KHIỂN VÀ NGƯỜI ĐƯỢC CHỞ trên xe mô tô, xe gắn máy nếu người được chở không đội mũ bảo hiểm hoặc cài quai không đúng quy cách.'),
(76,1,'Quy định chung và quy tắc giao thông đường bộ','Trong các trường hợp dưới đây, để bảo đảm an toàn khi tham gia giao thông, người lái xe mô tô cần thực hiện như thế nào?',null,'["Phải đội mũ bảo hiểm theo đúng quy chuẩn kỹ thuật quốc gia và cài quai đúng quy cách, không sử dụng ô, điện thoại di động, thiết bị âm thanh (trừ thiết bị trợ thính).","Phải đội mũ bảo hiểm khi trời mưa gió hoặc trời quá nắng; có thể sử dụng ô, điện thoại di động, thiết bị âm thanh nhưng phải bảo đảm an toàn.","Phải đội mũ bảo hiểm khi cảm thấy mất an toàn giao thông hoặc khi chuẩn bị di chuyển quãng đường xa."]'::jsonb,1,false,'Người lái mô tô an toàn phải: Đội mũ bảo hiểm đạt chuẩn, cài quai đúng quy cách; tuyệt đối không dùng ô, điện thoại di động hay tai nghe nhạc khi đang lái xe.'),
(77,1,'Quy định chung và quy tắc giao thông đường bộ','Thứ tự xuống phà như thế nào là đúng quy tắc giao thông?',null,'["Xe thô sơ, người đi bộ xuống trước, xe cơ giới, xe máy chuyên dùng xuống sau.","Xe cơ giới, xe máy chuyên dùng xuống trước, xe thô sơ, người đi bộ xuống sau.","Xe cơ giới, xe thô sơ xuống trước, xe máy chuyên dùng, người đi bộ xuống sau."]'::jsonb,2,false,'Quy tắc an toàn khi qua phà: Xe cơ giới, xe máy chuyên dùng phải xuống phà trước để ổn định trọng tâm phà; xe thô sơ và người đi bộ xuống sau cùng.'),
(78,1,'Quy định chung và quy tắc giao thông đường bộ','Trên đường có nhiều làn đường cho xe đi cùng chiều được phân biệt bằng vạch kẻ phân làn đường, người điều khiển phương tiện tham gia giao thông đường bộ phải cho xe đi như thế nào?',null,'["Cho xe đi trên bất kỳ làn đường nào hoặc giữa 02 làn đường nếu không có xe đi phía trước; khi cần thiết phải chuyển làn đường, người lái xe phải quan sát xe phía trước để bảo đảm an toàn.","Phải cho xe đi trong một làn đường và chỉ được chuyển làn đường ở những nơi cho phép; mỗi lần chuyển làn đường chỉ được phép chuyển sang một làn đường liền kề; khi chuyển làn đường phải có tín hiệu báo trước; phải quan sát bảo đảm khoảng cách an toàn với xe phía trước, phía sau và hai bên mới được chuyển làn.","Phải cho xe đi trong một làn đường, chỉ được chuyển làn đường khi vượt xe phía trước cùng làn đường."]'::jsonb,2,false,'Trên đường có nhiều làn cùng chiều: Xe phải đi trong MỘT LÀN ĐƯỜNG và chỉ được chuyển làn ở nơi cho phép; mỗi lần chuyển làn CHỈ ĐƯỢC CHUYỂN SANG MỘT LÀN LIỀN KỀ; phải bật tín hiệu báo trước và quan sát an toàn.'),
(79,1,'Quy định chung và quy tắc giao thông đường bộ','Trên đường một chiều có vạch kẻ phân làn đường, xe thô sơ và xe cơ giới phải đi như thế nào là đúng quy tắc giao thông?',null,'["Xe thô sơ phải đi trên làn đường bên trái, xe cơ giới, xe máy chuyên dùng đi trên làn đường bên phải trong cùng.","Xe thô sơ phải đi trên làn đường bên phải trong cùng, xe cơ giới, xe máy chuyên dùng đi trên làn đường bên trái.","Xe thô sơ phải đi trên làn đường bên phải trong cùng, xe cơ giới, xe máy chuyên dùng được đi trên tất cả các làn đường."]'::jsonb,2,false,'Trên đường một chiều có phân làn: Xe thô sơ phải đi trên làn bên PHẢI TRONG CÙNG; xe cơ giới, xe máy chuyên dùng đi trên các làn đường bên TRÁI.'),
(80,1,'Quy định chung và quy tắc giao thông đường bộ','Khi lái xe trong đô thị và khu đông dân cư trong thời gian từ 22 giờ ngày hôm trước đến 05 giờ ngày hôm sau, nếu cần vượt một xe khác, người lái xe phải báo hiệu như thế nào là đúng quy tắc giao thông?',null,'["Chỉ được báo hiệu bằng còi.","Phải báo hiệu bằng cả còi và đèn.","Chỉ được báo hiệu bằng đèn."]'::jsonb,3,false,'Từ 22 giờ hôm trước đến 05 giờ sáng hôm sau trong đô thị và khu đông dân cư, người lái xe muốn xin vượt CHỈ ĐƯỢC BÁO HIỆU BẰNG ĐÈN (nháy pha/cos), cấm bấm còi làm ảnh hưởng giấc ngủ của người dân.'),
(81,1,'Quy định chung và quy tắc giao thông đường bộ','Khi điều khiển xe chạy trên đường, biết có xe sau xin vượt, nếu đủ điều kiện an toàn người điều khiển phương tiện phải làm gì?',null,'["Tăng tốc độ và ra hiệu cho xe sau vượt, không được gây trở ngại cho xe xin vượt.","Giảm tốc độ, có tín hiệu rẽ phải để báo hiệu cho người điều khiển phương tiện tham gia giao thông đường bộ phía sau biết được vượt và đi sát về bên phải của phần đường xe chạy cho đến khi xe sau đã vượt qua, không được cản trở đối với xe xin vượt.","Cho xe đi sát về bên trái của phần đường xe chạy và ra hiệu cho xe sau vượt, không được gây trở ngại cho xe xin vượt."]'::jsonb,2,false,'Khi có xe sau xin vượt, nếu đủ an toàn, người lái xe phía trước phải giảm tốc độ, bật xi-nhan rẽ phải báo hiệu đồng ý và đi sát lề phải cho đến khi xe sau vượt qua hoàn toàn.'),
(82,1,'Quy định chung và quy tắc giao thông đường bộ','Khi điều khiển xe chạy trên đường, biết có xe sau xin vượt, nếu không đủ điều kiện an toàn người điều khiển phương tiện phải làm gì?',null,'["Có tín hiệu rẽ trái để báo hiệu cho người điều khiển phương tiện tham gia giao thông đường bộ phía sau biết là chưa được vượt.","Tiếp tục đi cho đến khi đủ điều kiện an toàn, nếu xe sau vẫn xin vượt thì báo hiệu cho xe sau vượt.","Tăng tốc độ để báo hiệu cho xe xin vượt biết là chưa được vượt."]'::jsonb,1,false,'Khi xe sau xin vượt nhưng thấy phía trước KHÔNG ĐỦ ĐIỀU KIỆN AN TOÀN (có chướng ngại vật, xe ngược chiều...), người lái xe phải BẬT TÍN HIỆU RẼ TRÁI để báo cho xe sau biết là CHƯA ĐƯỢC VƯỢT.'),
(83,1,'Quy định chung và quy tắc giao thông đường bộ','Khi chuyển hướng, người lái xe, người điều khiển xe máy chuyên dùng phải làm gì để bảo đảm an toàn?',null,'["Phải nhường đường cho người đi bộ, xe thô sơ, xe đi ngược chiều và chỉ chuyển hướng khi không gây trở ngại hoặc nguy hiểm cho người, phương tiện khác.","Nhanh chóng chuyển hướng để không gây trở ngại hoặc nguy hiểm cho người, phương tiện khác.","Ra tín hiệu chuyển hướng để yêu cầu các phương tiện khác dừng lại cho xe chuyển hướng di chuyển."]'::jsonb,1,false,'Khi chuyển hướng (rẽ), người lái xe phải quan sát kỹ, nhường đường cho người đi bộ, xe thô sơ và các xe đi ngược chiều, chỉ chuyển hướng khi hoàn toàn không gây trở ngại cho người khác.'),
(84,1,'Quy định chung và quy tắc giao thông đường bộ','Trước khi chuyển hướng, người điều khiển phương tiện tham gia giao thông đường bộ phải thực hiện như thế nào để bảo đảm an toàn?',null,'["Quan sát gương, nếu không có phương tiện gần hướng rẽ thì nhanh chóng chuyển hướng.","Quan sát, bảo đảm khoảng cách an toàn với xe phía sau, giảm tốc độ và có tín hiệu báo hướng rẽ hoặc có tín hiệu bằng tay theo hướng rẽ đối với xe thô sơ không có đèn báo hướng rẽ, chuyển dần sang làn gần nhất với hướng rẽ. Tín hiệu báo hướng rẽ hoặc tín hiệu bằng tay phải sử dụng liên tục trong quá trình chuyển hướng. Khi bảo đảm an toàn, không gây trở ngại cho người và phương tiện khác mới được chuyển hướng.","Quan sát gương, tăng tốc độ, ra tín hiệu và chuyển hướng."]'::jsonb,2,true,'🚨 [CÂU ĐIỂM LIỆT] Quy trình chuyển hướng: Phải quan sát an toàn, giảm tốc độ, bật xi-nhan báo rẽ liên tục, chuyển dần sang làn đường gần nhất với hướng rẽ, bảo đảm an toàn tuyệt đối mới được thực hiện chuyển hướng.'),
(85,1,'Quy định chung và quy tắc giao thông đường bộ','Khi lùi xe, người điều khiển phương tiện tham gia giao thông đường bộ phải làm gì để bảo đảm an toàn?',null,'["Quan sát phía sau và cho lùi xe ở tốc độ chậm.","Có tín hiệu báo lùi, nếu phía sau không có người hoặc phương tiện khác thì nhanh chóng lùi để bảo đảm an toàn.","Phải quan sát hai bên và phía sau xe, có tín hiệu lùi và chỉ lùi xe khi bảo đảm an toàn."]'::jsonb,3,false,'Khi lùi xe, người lái xe phải quan sát kỹ hai bên gương và phía sau xe, bật đèn lùi/tín hiệu cảnh báo lùi và chỉ lùi khi chắc chắn không có chướng ngại vật hoặc phương tiện phía sau.'),
(86,1,'Quy định chung và quy tắc giao thông đường bộ','Khi muốn lùi xe ở nơi có tầm nhìn bị che khuất, người lái xe phải xử lý như thế nào để đảm bảo an toàn?',null,'["Phải lùi thật chậm.","Bấm còi 3 lần liên tiếp trước khi lùi.","Không được lùi xe."]'::jsonb,3,false,'Ở nơi có tầm nhìn bị che khuất (như góc cua hẹp, ngã ba khuất...), người lái xe KHÔNG ĐƯỢC LÙI XE vì không thể quan sát được dòng phương tiện tiếp cận phía sau.'),
(87,1,'Quy định chung và quy tắc giao thông đường bộ','Trên đường không phân chia thành hai chiều xe chạy riêng biệt, người điều khiển phương tiện tham gia giao thông đường bộ phải tránh xe đi ngược chiều như thế nào để bảo đảm an toàn?',null,'["Giảm tốc độ và cho xe đi về bên phải theo chiều xe chạy của mình.","Một trong hai xe phải dừng lại cho xe kia đi qua mới được đi.","Tăng tốc độ, cho xe đi về bên phải theo chiều xe chạy của mình để nhanh chóng vượt qua."]'::jsonb,1,true,'🚨 [CÂU ĐIỂM LIỆT] Khi tránh xe đi ngược chiều trên đường hai chiều hẹp, người lái xe phải GIẢM TỐC ĐỘ và cho xe đi sát về bên PHẢI theo chiều đi của mình. Tuyệt đối không được lấn làn hay tăng tốc.'),
(88,1,'Quy định chung và quy tắc giao thông đường bộ','Khi tránh xe đi ngược chiều, các xe phải nhường đường như thế nào là đúng quy tắc giao thông?',null,'["Nơi đường hẹp chỉ đủ cho một xe chạy và có chỗ tránh xe thì xe nào ở gần chỗ tránh hơn phải vào vị trí tránh, nhường đường cho xe đi ngược chiều.","Xe xuống dốc phải nhường đường cho xe lên dốc.","Xe có chướng ngại vật phía trước phải nhường đường cho xe không có chướng ngại vật phía trước.","Cả ba ý trên."]'::jsonb,4,false,'Quy tắc nhường đường khi tránh xe ngược chiều: 1. Xe gần chỗ tránh hơn phải vào vị trí tránh nhường đường; 2. Xe xuống dốc phải nhường đường cho xe đang lên dốc; 3. Xe có chướng ngại vật phía trước phải nhường cho xe không có vật cản.'),
(89,1,'Quy định chung và quy tắc giao thông đường bộ','Khi đang lái xe xuống dốc gặp một xe đang đi lên dốc, người lái xe phải làm gì?',null,'["Tiếp tục đi và phát tín hiệu cho xe lên dốc nhường đường cho xe bạn.","Nhường đường cho xe lên dốc.","Chỉ nhường đường khi xe lên dốc nháy đèn."]'::jsonb,2,false,'Khi hai xe gặp nhau trên dốc hẹp, xe ĐANG XUỐNG DỐC phải dừng lại nhường đường cho xe ĐANG LÊN DỐC (vì xe lên dốc cần đà và khó khởi hành lại hơn).'),
(90,1,'Quy định chung và quy tắc giao thông đường bộ','Người lái xe phải làm gì để bảo đảm an toàn khi lái xe trên đường cong có tầm nhìn bị hạn chế?',null,'["Quan sát, giảm tốc độ hoặc dừng lại để bảo đảm an toàn.","Đi sang làn đường của xe ngược chiều để mở rộng tầm nhìn và vượt xe khác.","Cho xe đi sát bên phải làn đường, bật tín hiệu báo hiệu để vượt bên phải xe khác."]'::jsonb,1,false,'Khi lái xe trên đường cong có tầm nhìn bị hạn chế (khuất cua), người lái xe bắt buộc phải QUAN SÁT VÀ GIẢM TỐC ĐỘ, đi đúng làn đường của mình. Nghiêm cấm lấn làn hoặc vượt xe tại góc cua.'),
(91,1,'Quy định chung và quy tắc giao thông đường bộ','Tại nơi đường giao nhau, người lái xe đang đi trên đường không ưu tiên, đường nhánh phải nhường đường như thế nào là đúng quy tắc giao thông?',null,'["Nhường đường cho xe đi ở bên phải mình tới.","Nhường đường cho xe đi ở bên trái mình tới.","Nhường đường cho xe đi trên đường ưu tiên hoặc đường chính từ bất kỳ hướng nào tới."]'::jsonb,3,true,'🚨 [CÂU ĐIỂM LIỆT] Tại nơi giao nhau, xe đi từ đường nhánh, đường không ưu tiên bắt buộc phải NHƯỜNG ĐƯỜNG cho xe đi trên đường chính, đường ưu tiên TỪ BẤT KỲ HƯỚNG NÀO TỚI.'),
(92,1,'Quy định chung và quy tắc giao thông đường bộ','Tại nơi đường giao nhau có báo hiệu đi theo vòng xuyến, người lái xe phải nhường đường như thế nào là đúng quy tắc giao thông?',null,'["Nhường đường cho xe đi đến từ bên phải.","Nhường đường cho xe đi đến từ bên trái.","Không phải nhường đường."]'::jsonb,2,true,'🚨 [CÂU ĐIỂM LIỆT] Mẹo nhớ quy tắc vòng xuyến: ''CÓ vòng xuyến nhường BÊN TRÁI; KHÔNG vòng xuyến nhường BÊN PHẢI''. Tại nơi giao nhau có báo hiệu vòng xuyến, phải nhường đường cho xe đến từ bên trái.'),
(93,1,'Quy định chung và quy tắc giao thông đường bộ','Tại nơi đường giao nhau không có báo hiệu đi theo vòng xuyến, người điều khiển phương tiện phải nhường đường như thế nào là đúng quy tắc giao thông?',null,'["Phải nhường đường cho xe đi đến từ bên phải.","Xe báo hiệu xin đường trước, xe đó được đi trước.","Phải nhường đường cho xe đi đến từ bên trái."]'::jsonb,1,true,'🚨 [CÂU ĐIỂM LIỆT] Mẹo nhớ quy tắc giao nhau: ''KHÔNG vòng xuyến nhường BÊN PHẢI''. Tại ngã tư không có biển báo vòng xuyến, người lái xe bắt buộc phải nhường đường cho xe đi đến từ bên phải.'),
(94,1,'Quy định chung và quy tắc giao thông đường bộ','Người lái xe phải nhanh chóng giảm tốc độ, đi sát lề đường bên phải hoặc dừng lại để nhường đường cho các loại xe nào dưới đây?',null,'["Xe chữa cháy của Cảnh sát phòng cháy, chữa cháy và cứu nạn, cứu hộ và xe chữa cháy của các lực lượng khác; xe của lực lượng quân sự, công an và kiểm sát; đoàn xe có xe Cảnh sát giao thông dẫn đường; xe cứu thương; xe hộ đê không có tín hiệu ưu tiên theo quy định.","Xe ưu tiên gồm xe chữa cháy của Cảnh sát phòng cháy, chữa cháy và cứu nạn, cứu hộ và xe chữa cháy của các lực lượng khác được huy động đi làm nhiệm vụ chữa cháy; xe của lực lượng quân sự, công an và kiểm sát đi làm nhiệm vụ khẩn cấp; đoàn xe có xe Cảnh sát giao thông dẫn đường; xe cứu thương đi làm nhiệm vụ cấp cứu; xe hộ đê đi làm nhiệm vụ; xe đi làm nhiệm vụ cứu nạn, cứu hộ, khắc phục sự cố thiên tai, dịch bệnh hoặc xe đi làm nhiệm vụ trong tình trạng khẩn cấp theo quy định của pháp luật; đoàn xe tang.","Xe ô tô, xe máy, đoàn xe đang diễu hành có tổ chức có báo tín hiệu xin vượt bằng còi và đèn."]'::jsonb,2,true,'🚨 [CÂU ĐIỂM LIỆT] Người lái xe phải giảm tốc độ, đi sát lề phải hoặc dừng lại nhường đường cho các xe ưu tiên đang phát tín hiệu: xe chữa cháy, quân sự, công an, kiểm sát làm nhiệm vụ, đoàn xe có CSGT dẫn đường, xe cứu thương, xe hộ đê, cứu hộ khẩn cấp và đoàn xe tang.'),
(95,1,'Quy định chung và quy tắc giao thông đường bộ','Xe ưu tiên (trừ đoàn xe tang) tham gia giao thông đường bộ khi đi làm nhiệm vụ được quyền ưu tiên nào dưới đây?',null,'["Không bị hạn chế tốc độ.","Được phép đi không phụ thuộc vào tín hiệu đèn giao thông, đi vào đường ngược chiều, các đường khác có thể đi được.","Được đi ngược chiều trên làn dừng xe khẩn cấp trên đường cao tốc.","Cả ba ý trên."]'::jsonb,4,false,'Xe ưu tiên khi đi làm nhiệm vụ khẩn cấp (có tín hiệu còi, đèn ưu tiên): không bị hạn chế tốc độ, được phép vượt đèn đỏ, được đi vào đường ngược chiều và được đi ngược chiều trên làn khẩn cấp của cao tốc.'),
(96,1,'Quy định chung và quy tắc giao thông đường bộ','Khi có tín hiệu của xe ưu tiên, người và phương tiện tham gia giao thông đường bộ phải tuân thủ quy định nào dưới đây?',null,'["Giảm tốc độ, đi sát lề đường bên phải hoặc dừng lại để nhường đường.","Tăng tốc độ và đi sát lề đường bên phải để nhường đường.","Giảm tốc độ, đi sát lề đường bên trái để nhường đường."]'::jsonb,1,true,'🚨 [CÂU ĐIỂM LIỆT] Khi nghe thấy tín hiệu còi, đèn ưu tiên, mọi phương tiện tham gia giao thông phải lập tức GIẢM TỐC ĐỘ, đi sát lề đường bên PHẢI hoặc dừng lại để nhường đường, tuyệt đối không cản trở xe ưu tiên.'),
(97,1,'Quy định chung và quy tắc giao thông đường bộ','Khi đang lái xe, phía trước có một xe Cảnh sát giao thông không phát tín hiệu ưu tiên, người lái xe có được phép vượt hay không?',null,'["Không được vượt.","Được phép vượt ở phần đường dành cho người đi bộ qua đường.","Được vượt khi bảo đảm an toàn."]'::jsonb,3,false,'Nếu xe Cảnh sát giao thông chạy phía trước KHÔNG PHÁT TÍN HIỆU ƯU TIÊN (không bật còi, đèn nhấp nháy làm nhiệm vụ), người lái xe ĐƯỢC PHÉP VƯỢT khi bảo đảm an toàn và tuân thủ tốc độ quy định.'),
(98,1,'Quy định chung và quy tắc giao thông đường bộ','Khi đang lái xe, phía trước có một xe cứu thương đang phát tín hiệu ưu tiên, người lái xe có được phép vượt hay không?',null,'["Không được vượt.","Được vượt khi đang đi trên cầu.","Được phép vượt khi đi qua nơi giao nhau có ít phương tiện cùng tham gia giao thông.","Được vượt khi bảo đảm an toàn."]'::jsonb,1,false,'Khi xe cứu thương đang phát tín hiệu còi, đèn ưu tiên làm nhiệm vụ cấp cứu, người lái xe TUYỆT ĐỐI KHÔNG ĐƯỢC VƯỢT trong bất kỳ hoàn cảnh nào.'),
(99,1,'Quy định chung và quy tắc giao thông đường bộ','Khi tới đường ngang không có người gác, chắn đường bộ, chuông, đèn tín hiệu, người tham gia giao thông đường bộ phải làm gì để bảo đảm an toàn?',null,'["Dừng lại về bên phải đường của mình, trước vạch dừng xe và quan sát hai phía, khi không có phương tiện giao thông đường sắt tới mới được đi qua.","Quan sát hai phía, khi không có phương tiện giao thông đường sắt tới thì nhanh chóng đi qua.","Dừng lại khoảng cách tối thiểu 3 mét tính từ ray đường sắt gần nhất, khi không có phương tiện giao thông đường sắt tới thì nhanh chóng đi qua."]'::jsonb,1,false,'Tại đường ngang không có rào chắn, chuông đèn: Người lái xe phải dừng lại bên phải đường trước vạch dừng, quan sát kỹ hai phía đường ray, khi chắc chắn không có tàu hỏa tới mới được lái xe qua.'),
(100,1,'Quy định chung và quy tắc giao thông đường bộ','Tại đường ngang, cầu chung đường sắt, khi có hiệu lệnh của nhân viên gác chắn, đèn đỏ sáng nhấp nháy, chuông kêu, chắn đường bộ đang dịch chuyển hoặc đã đóng, người tham gia giao thông đường bộ phải làm gì để bảo đảm an toàn?',null,'["Dừng lại về bên trái đường của mình, trước vạch dừng xe.","Dừng lại giữa đường của mình, trước vạch dừng xe.","Dừng lại về bên phải đường của mình, trước vạch dừng xe."]'::jsonb,3,false,'Tại nơi giao nhau với đường sắt, khi có chuông kêu, đèn đỏ nhấp nháy hoặc cần chắn đang hạ xuống, người tham gia giao thông phải DỪNG LẠI VỀ BÊN PHẢI đường của mình, phía trước vạch dừng xe.');
insert into questions(id,chapter,chapter_name,question,image,options,correct_option,is_critical,explanation) values
(101,1,'Quy định chung và quy tắc giao thông đường bộ','Khi xe ô tô bị hư hỏng, bị tai nạn trên đường ngang, cầu chung đường sắt mà không thể di chuyển ngay khỏi phạm vi an toàn đường sắt, người lái xe và người có mặt xử lý như thế nào là đúng quy định?',null,'["Người lái xe và người có mặt phải ngay lập tức báo hiệu để dừng tàu, thực hiện các biện pháp bảo đảm an toàn.","Để xe lại, tìm cách báo cho người quản lý đường sắt, nhà ga nơi gần nhất.","Không di chuyển phương tiện, tự khắc phục sửa chữa."]'::jsonb,1,true,'🚨 [CÂU ĐIỂM LIỆT] Khi xe bị chết máy, tai nạn nằm trên đường ray mà không thể di chuyển ra ngoài phạm vi an toàn, người lái xe và mọi người có mặt phải NGAY LẬP TỨC báo hiệu để dừng tàu (chạy về hai phía tối thiểu 500m phát tín hiệu) và thực hiện các biện pháp an toàn khẩn cấp.'),
(102,1,'Quy định chung và quy tắc giao thông đường bộ','Người tham gia giao thông đường bộ phải dừng lại về bên phải đường của mình trước vạch dừng xe tại đường ngang, cầu chung đường sắt khi có báo hiệu nào dưới đây?',null,'["Hiệu lệnh của nhân viên gác chắn.","Đèn đỏ sáng nhấp nháy, chuông kêu.","Chắn đường bộ đang dịch chuyển hoặc đã đóng.","Cả ba ý trên."]'::jsonb,4,false,'Phải dừng lại bên phải trước vạch dừng khi: có hiệu lệnh nhân viên gác chắn, đèn đỏ nhấp nháy/chuông kêu, hoặc rào chắn đường sắt đang dịch chuyển/đã đóng kín.'),
(103,1,'Quy định chung và quy tắc giao thông đường bộ','Người điều khiển phương tiện tham gia giao thông trong hầm đường bộ ngoài việc phải tuân thủ các quy tắc giao thông còn phải thực hiện những quy định nào dưới đây?',null,'["Xe cơ giới, xe máy chuyên dùng phải bật đèn chiếu gần; xe thô sơ phải bật đèn hoặc có vật phát sáng báo hiệu; không dừng xe, đỗ xe trong hầm đường bộ; trường hợp gặp sự cố kỹ thuật hoặc bất khả kháng khác buộc phải dừng xe, đỗ xe, người lái xe, người điều khiển xe máy chuyên dùng phải đưa xe vào vị trí dừng xe, đỗ xe khẩn cấp, nếu không di chuyển được, phải có báo hiệu bằng đèn khẩn cấp và đặt biển hoặc đèn cảnh báo về phía sau xe khoảng cách bảo đảm an toàn.","Xe cơ giới, xe máy chuyên dùng phải bật đèn chiếu xa; được dừng xe, đỗ xe khi cần thiết.","Phải cho xe chạy trên một làn đường và chỉ chuyển làn ở nơi được phép; được quay đầu xe, lùi xe khi cần thiết."]'::jsonb,1,false,'Quy tắc lái xe trong hầm đường bộ: Bắt buộc bật đèn chiếu gần (cốt); xe thô sơ phải có đèn hoặc vật phát sáng; CẤM dừng, đỗ, quay đầu hoặc lùi xe trong hầm. Nếu gặp sự cố phải đưa vào vị trí dừng khẩn cấp và đặt cảnh báo an toàn.'),
(104,1,'Quy định chung và quy tắc giao thông đường bộ','Việc nối giữa xe kéo với xe được kéo trong trường hợp hệ thống hãm của xe được kéo không còn hiệu lực thì xe kéo nhau phải nối bằng cách nào?',null,'["Nối bằng dây cáp có độ dài 6 mét.","Nối bằng dây cáp có độ dài 8 mét.","Nối bằng thanh nối cứng."]'::jsonb,3,false,'Khi kéo xe ô tô bị hỏng mà hệ thống phanh (hãm) của xe được kéo không còn hiệu lực, bắt buộc phải sử dụng THANH NỐI CỨNG để xe trước có thể hãm hộ xe sau, cấm dùng dây cáp mềm vì xe sau sẽ đâm vào xe trước khi phanh.'),
(105,1,'Quy định chung và quy tắc giao thông đường bộ','Xe kéo rơ moóc, xe ô tô đầu kéo khi tham gia giao thông đường bộ phải tuân thủ quy tắc giao thông nào ghi ở dưới đây?',null,'["Chỉ được kéo rơ moóc, sơ mi rơ moóc phù hợp với thiết kế của xe; việc kết nối xe kéo với rơ moóc, xe ô tô đầu kéo với sơ mi rơ moóc phải bảo đảm chắc chắn, an toàn.","Phải có tổng trọng lượng tương đương tổng trọng lượng của rơ moóc hoặc phải có hệ thống hãm có hiệu lực cho rơ moóc.","Phải được lắp phanh phụ theo quy định để đảm bảo an toàn."]'::jsonb,1,false,'Xe kéo rơ moóc, ô tô đầu kéo phải kéo rơ moóc phù hợp thiết kế và tải trọng cho phép; chốt kết nối phải chắc chắn, có xích an toàn theo quy định.'),
(106,1,'Quy định chung và quy tắc giao thông đường bộ','Luật Trật tự, an toàn giao thông đường bộ quy định về xe kéo xe, xe kéo rơ moóc và xe ô tô đầu kéo kéo sơ mi rơ moóc như thế nào dưới đây?',null,'["Một xe ô tô được kéo theo nhiều xe ô tô hoặc xe máy chuyên dùng khác khi xe được kéo không tự chạy được (trừ trường hợp xe vận chuyển hàng siêu trường, siêu trọng).","Xe được kéo phải có người điều khiển và hệ thống lái của xe đó phải còn hiệu lực; việc nối xe kéo với xe được kéo phải bảo đảm chắc chắn, an toàn; trường hợp hệ thống hãm của xe được kéo không còn hiệu lực thì xe kéo nhau phải nối bằng thanh nối cứng. Phía trước của xe kéo và phía sau của xe được kéo phải có biển báo hiệu, có đèn cảnh báo nhấp nháy màu vàng.","Cả hai ý trên."]'::jsonb,2,false,'Quy tắc kéo xe: Xe được kéo phải có người ngồi lái và hệ thống lái hoạt động bình thường; nếu mất phanh phải nối bằng thanh nối cứng; phía trước xe kéo và sau xe được kéo phải gắn biển báo hiệu và bật đèn vàng cảnh báo.'),
(107,1,'Quy định chung và quy tắc giao thông đường bộ','Người điều khiển phương tiện tham gia giao thông đường bộ phải quan sát, giảm tốc độ hoặc dừng lại để bảo đảm an toàn trong các trường hợp nào dưới đây?',null,'["Có báo hiệu cảnh báo nguy hiểm hoặc có chướng ngại vật trên đường; chuyển hướng xe chạy hoặc tầm nhìn bị hạn chế.","Nơi cầu, cống hẹp, đập tràn, đường ngầm, hầm chui, hầm đường bộ; có vật nuôi đi trên đường hoặc chăn thả ở ven đường.","Điểm dừng xe, đỗ xe trên đường bộ có khách đang lên, xuống xe.","Cả ba ý trên."]'::jsonb,4,true,'🚨 [CÂU ĐIỂM LIỆT] Người lái xe phải quan sát, giảm tốc độ hoặc dừng lại khi: gặp biển báo nguy hiểm/chướng ngại vật, chuyển hướng, cầu cống hẹp, ngầm, đường dốc, có vật nuôi trên đường, hoặc tại trạm xe buýt đang có hành khách lên xuống.'),
(108,1,'Quy định chung và quy tắc giao thông đường bộ','Trên đường mà mỗi chiều đường xe chạy chỉ có một làn đường dành cho xe cơ giới, người lái xe không được vượt xe khác trong trường hợp nào dưới đây?',null,'["Có chướng ngại vật phía trước, xe chạy phía trước có tín hiệu vượt xe khác.","Xe chạy phía trước đã có tín hiệu rẽ phải và tránh về bên phải.","Cả hai ý trên."]'::jsonb,1,false,'Trên đường có một làn xe cơ giới mỗi chiều, không được vượt xe khi: có chướng ngại vật phía trước, hoặc xe chạy phía trước đã có tín hiệu chuẩn bị vượt xe khác.'),
(109,1,'Quy định chung và quy tắc giao thông đường bộ','Người lái xe được phép vượt xe khác về bên phải trong trường hợp nào dưới đây?',null,'["Xe phía trước có tín hiệu rẽ trái hoặc đang rẽ trái hoặc khi xe chuyên dùng đang làm việc trên đường mà không thể vượt bên trái.","Xe phía trước đang đi sát lề đường bên trái.","Cả hai ý trên."]'::jsonb,1,false,'Được phép vượt bên phải trong 3 trường hợp: 1. Khi xe phía trước có tín hiệu rẽ trái hoặc đang rẽ trái; 2. Khi xe điện đang chạy giữa đường; 3. Khi xe chuyên dùng đang thi công trên đường không thể vượt bên trái.'),
(110,1,'Quy định chung và quy tắc giao thông đường bộ','Khi có xe xin vượt, người lái xe mô tô xử lý như thế nào nếu đủ điều kiện an toàn cho xe phía sau vượt?',null,'["Giảm tốc độ, có tín hiệu rẽ phải để báo hiệu cho người điều khiển phương tiện tham gia giao thông đường bộ phía sau biết được vượt và đi sát về bên phải của phần đường xe chạy cho đến khi xe sau đã vượt qua, không được cản trở đối với xe xin vượt.","Lái xe vào lề đường bên trái và giảm tốc độ để xe phía sau vượt qua, không được gây trở ngại đối với xe xin vượt.","Tăng tốc độ, đi sát về bên phải của phần đường xe chạy cho đến khi xe sau đã vượt qua."]'::jsonb,1,false,'Khi có xe sau xin vượt, nếu đủ điều kiện an toàn, người lái xe phải giảm tốc độ, bật đèn xi-nhan rẽ phải báo hiệu đồng ý và đi sát mép đường bên phải cho đến khi xe sau vượt qua.'),
(111,1,'Quy định chung và quy tắc giao thông đường bộ','Những trường hợp nào dưới đây không được đi trên đường cao tốc, trừ người, phương tiện giao thông đường bộ và thiết bị phục vụ việc quản lý, bảo trì đường cao tốc?',null,'["Xe máy chuyên dùng có tốc độ thiết kế nhỏ hơn tốc độ tối thiểu quy định đối với đường cao tốc, xe chở người bốn bánh có gắn động cơ, xe chở hàng bốn bánh có gắn động cơ, xe mô tô, xe gắn máy, các loại xe tương tự xe mô tô, xe gắn máy, xe thô sơ, người đi bộ.","Xe máy chuyên dùng có tốc độ thiết kế lớn hơn tốc độ tối thiểu quy định đối với đường cao tốc.","Xe ô tô và xe máy chuyên dùng có tốc độ thiết kế lớn hơn 80 km/h."]'::jsonb,1,false,'Các phương tiện KHÔNG ĐƯỢC đi vào đường cao tốc: Người đi bộ, xe thô sơ, xe mô tô, xe gắn máy, xe 4 bánh chở người/hàng có gắn động cơ, và xe máy chuyên dùng có tốc độ thiết kế NHỎ HƠN tốc độ tối thiểu của đường cao tốc.'),
(112,1,'Quy định chung và quy tắc giao thông đường bộ','Khi tham gia giao thông trên đường cao tốc, xe ưu tiên đi làm nhiệm vụ khẩn cấp được đi ngược chiều trong trường hợp nào dưới đây?',null,'["Được đi ngược chiều bất cứ làn đường nào của đường cao tốc có thể đi được.","Chỉ được đi ngược chiều trên làn dừng xe khẩn cấp.","Chỉ được đi ngược chiều trên làn đường sát dải phân cách của đường cao tốc."]'::jsonb,2,false,'Theo Luật Trật tự, ATGT đường bộ mới: Xe ưu tiên đi làm nhiệm vụ khẩn cấp nếu đi ngược chiều trên đường cao tốc thì CHỈ ĐƯỢC ĐI NGƯỢC CHIỀU TRÊN LÀN DỪNG XE KHẨN CẤP để bảo đảm an toàn cho các làn xe đang chạy tốc độ cao.'),
(113,1,'Quy định chung và quy tắc giao thông đường bộ','Khi tham gia giao thông trên đường cao tốc, người lái xe không được thực hiện hành vi nào sau đây?',null,'["Dừng, đỗ xe trên phần đường xe chạy, trừ trường hợp xe không thể di chuyển được vào làn đường khẩn cấp.","Lùi xe, quay đầu xe.","Cả hai ý trên."]'::jsonb,3,false,'Trên đường cao tốc, nghiêm cấm người lái xe: Dừng đỗ xe trên làn đường xe chạy (trừ xe hỏng bất khả kháng), lùi xe, hoặc quay đầu xe.'),
(114,1,'Quy định chung và quy tắc giao thông đường bộ','Khi xe gặp sự cố kỹ thuật trên đường cao tốc, bạn phải xử lý như thế nào để bảo đảm an toàn giao thông?',null,'["Bật đèn tín hiệu khẩn cấp, dừng xe ngay lập tức và đặt biển báo hiệu nguy hiểm để cảnh báo cho các xe khác.","Bật tín hiệu khẩn cấp, lập tức đưa xe vào làn đường xe chạy bên phải trong cùng, đặt biển báo hiệu nguy hiểm để cảnh báo cho các xe khác.","Dừng xe, đỗ xe ở làn dừng khẩn cấp cùng chiều xe chạy và phải có báo hiệu bằng đèn khẩn cấp; trường hợp xe không thể di chuyển được vào làn dừng khẩn cấp, phải có báo hiệu bằng đèn khẩn cấp và đặt biển hoặc đèn cảnh báo về phía sau xe khoảng cách tối thiểu 150 mét, nhanh chóng báo cho cơ quan Cảnh sát giao thông thực hiện nhiệm vụ bảo đảm trật tự, an toàn giao thông trên tuyến hoặc cơ quan quản lý đường cao tốc."]'::jsonb,3,false,'Khi gặp sự cố trên cao tốc: Phải bật đèn khẩn cấp, cố gắng đưa xe vào làn dừng khẩn cấp; nếu xe không lăn bánh được, phải bật đèn cảnh báo nguy hiểm và ĐẶT BIỂN/ĐÈN CẢNH BÁO PHÍA SAU XE TỐI THIỂU 150 MÉT, đồng thời gọi điện cứu hộ.'),
(115,1,'Quy định chung và quy tắc giao thông đường bộ','Trên đường cao tốc, người lái xe xử lý như thế nào khi đã vượt quá lối ra của đường định rẽ?',null,'["Quay đầu xe, chạy trên lề đường có lối ra và rẽ khỏi đường cao tốc.","Lùi xe trên lề đường có lối ra và rẽ khỏi đường cao tốc.","Tiếp tục lái xe và rẽ ở lối ra tiếp theo."]'::jsonb,3,true,'🚨 [CÂU ĐIỂM LIỆT] Khi lái xe trên đường cao tốc mà lỡ đi quá lối rẽ, tuyệt đối KHÔNG ĐƯỢC lùi xe hay quay đầu chạy ngược chiều (nguy cơ va chạm liên hoàn thảm khốc), mà bắt buộc phải TIẾP TỤC ĐI THẲNG đến nút giao/lối ra tiếp theo.'),
(116,1,'Quy định chung và quy tắc giao thông đường bộ','Khi xảy ra ùn tắc trên đường cao tốc có làn dừng xe khẩn cấp, người lái xe có được cho xe chạy ở làn dừng xe khẩn cấp để nhanh chóng thoát khỏi khu vực ùn tắc không (trừ xe ưu tiên)?',null,'["Có.","Không."]'::jsonb,2,false,'Khi xảy ra ùn tắc trên đường cao tốc, người lái xe TUYỆT ĐỐI KHÔNG ĐƯỢC chạy vào làn dừng khẩn cấp để vượt lên, vì làn này dành riêng cho các phương tiện cứu nạn, cứu thương, công an tiếp cận hiện trường.'),
(117,1,'Quy định chung và quy tắc giao thông đường bộ','Khi chuẩn bị nhập vào làn đường của đường cao tốc, người lái xe, người điều khiển xe máy chuyên dùng phải thực hiện như thế nào là đúng quy tắc giao thông?',null,'["Có tín hiệu xin vào và phải nhường đường cho xe đang chạy trên đường.","Quan sát xe phía sau bảo đảm khoảng cách an toàn mới cho xe nhập vào làn đường sát bên phải.","Nếu có làn đường tăng tốc thì phải cho xe chạy trên làn đường đó trước khi nhập vào làn đường của đường cao tốc.","Cả ba ý trên."]'::jsonb,4,false,'Quy tắc nhập làn cao tốc: Bật xi-nhan xin vào, quan sát nhường đường cho xe đang chạy trên cao tốc; nếu có làn tăng tốc thì phải tăng tốc độ tương đương dòng xe trước khi chuyển làn an toàn.'),
(118,1,'Quy định chung và quy tắc giao thông đường bộ','Theo quy định về độ tuổi, người đủ bao nhiêu tuổi trở lên thì được cấp giấy phép lái xe ô tô tải và ô tô chuyên dùng có khối lượng toàn bộ theo thiết kế trên 3.500 kg đến 7.500 kg; các loại xe ô tô tải quy định cho giấy phép lái xe hạng C1 kéo rơ moóc có khối lượng toàn bộ theo thiết kế đến 750 kg?',null,'["18 tuổi.","17 tuổi.","16 tuổi."]'::jsonb,1,false,'Theo Luật mới: Người đủ 18 tuổi trở lên được cấp GPLX hạng C1 (lái xe ô tô tải có khối lượng từ trên 3.500 kg đến 7.500 kg; kéo rơ moóc đến 750 kg).'),
(119,1,'Quy định chung và quy tắc giao thông đường bộ','Theo quy định về độ tuổi, người đủ bao nhiêu tuổi trở lên thì được cấp giấy phép lái xe mô tô hai bánh có dung tích xi lanh đến 125 cm3 và xe ô tô chở người đến 8 chỗ (không kể chỗ của người lái xe); xe ô tô tải và ô tô chuyên dùng có khối lượng toàn bộ theo thiết kế đến 3.500 kg?',null,'["16 tuổi.","17 tuổi","18 tuổi."]'::jsonb,3,true,'🚨 [CÂU ĐIỂM LIỆT] Độ tuổi cấp GPLX: Người đủ 18 tuổi trở lên được cấp GPLX hạng A1 (mô tô đến 125 cm3) và hạng B (ô tô chở người đến 8 chỗ, ô tô tải đến 3.500 kg). Người từ 16 đến dưới 18 tuổi chỉ được lái xe gắn máy dưới 50 cm3.'),
(120,1,'Quy định chung và quy tắc giao thông đường bộ','Theo quy định về độ tuổi, người lái xe ô tô chở người (kể cả xe buýt) trên 29 chỗ (không kể chỗ của người lái xe); xe ô tô chở người giường nằm; các loại xe ô tô chở người quy định cho giấy phép lái xe hạng D kéo rơ moóc có khối lượng toàn bộ theo thiết kế đến 750 kg phải đủ bao nhiêu tuổi trở lên?',null,'["23 tuổi.","24 tuổi.","27 tuổi.","30 tuổi."]'::jsonb,3,false,'Độ tuổi lái xe khách lớn: Người đủ 27 tuổi trở lên mới được cấp GPLX hạng D (lái xe chở người trên 29 chỗ, xe khách giường nằm).'),
(121,1,'Quy định chung và quy tắc giao thông đường bộ','Tuổi tối đa của người lái xe ô tô chở người (kể cả xe buýt) trên 29 chỗ (không kể chỗ của người lái xe), xe ô tô chở người giường nằm là bao nhiêu tuổi?',null,'["Đủ 55 tuổi đối với nam và đủ 50 tuổi đối với nữ.","Đủ 55 tuổi đối với nam và nữ.","Đủ 57 tuổi đối với nam và đủ 55 tuổi đối với nữ."]'::jsonb,3,false,'Theo Luật Trật tự, an toàn giao thông đường bộ 2024: Độ tuổi tối đa của người lái xe ô tô chở người trên 29 chỗ, xe khách giường nằm là đủ 57 tuổi đối với nam và đủ 55 tuổi đối với nữ.'),
(122,1,'Quy định chung và quy tắc giao thông đường bộ','Theo quy định về độ tuổi, người lái xe ô tô chở người (kể cả xe buýt) trên 16 chỗ (không kể chỗ của người lái xe) đến 29 chỗ (không kể chỗ của người lái xe); các loại xe ô tô chở người quy định cho giấy phép lái xe hạng D2 kéo rơ moóc có khối lượng toàn bộ theo thiết kế đến 750 kg phải đủ bao nhiêu tuổi trở lên?',null,'["23 tuổi.","24 tuổi.","22 tuổi."]'::jsonb,2,false,'Độ tuổi lái xe ô tô chở người từ trên 16 chỗ đến 29 chỗ (hạng D2) là đủ 24 tuổi trở lên.'),
(123,1,'Quy định chung và quy tắc giao thông đường bộ','Người đủ 16 tuổi đến dưới 18 tuổi chỉ được điều khiển các loại xe nào dưới đây?',null,'["Xe mô tô hai bánh có dung tích xi-lanh đến 125 cm3.","Xe gắn máy.","Xe ô tô chở người đến 08 chỗ (không kể chỗ của người lái xe); xe ô tô tải và ô tô chuyên dùng có khối lượng toàn bộ theo thiết kế đến 3.500 kg; các loại xe ô tô quy định cho giấy phép lái xe hạng B kéo rơ moóc có khối lượng toàn bộ theo thiết kế đến 750 kg.","Cả ba ý trên."]'::jsonb,2,false,'Người đủ từ 16 tuổi đến dưới 18 tuổi CHỈ ĐƯỢC PHÉP điều khiển xe gắn máy (có dung tích xi-lanh dưới 50 cm3 hoặc xe máy điện có công suất động cơ điện không quá 4 kW). Chưa được cấp bằng lái ô tô hoặc mô tô.'),
(124,1,'Quy định chung và quy tắc giao thông đường bộ','Người có Giấy phép lái xe mô tô hạng A1 không được phép điều khiển loại xe nào dưới đây?',null,'["Xe mô tô hai bánh có dung tích xi-lanh 125 cm3 hoặc có công suất động cơ điện đến 11 kW.","Xe mô tô ba bánh.","Cả hai ý trên."]'::jsonb,2,false,'Người có GPLX hạng A1 KHÔNG ĐƯỢC PHÉP điều khiển xe mô tô ba bánh (xe ba bánh dành riêng cho thương binh, người khuyết tật yêu cầu giấy phép lái xe chuyên biệt).'),
(125,1,'Quy định chung và quy tắc giao thông đường bộ','Người có Giấy phép lái xe mô tô hạng A1 được cấp sau ngày 01/01/2025 được phép điều khiển loại xe nào dưới đây?',null,'["Xe mô tô hai bánh có dung tích xi-lanh đến 125 cm3 hoặc có công suất động cơ điện đến 11 kW.","Xe mô tô ba bánh.","Cả hai ý trên."]'::jsonb,1,false,'Theo Luật mới áp dụng từ 01/01/2025: Giấy phép lái xe hạng A1 cấp cho người lái xe mô tô hai bánh có dung tích xi-lanh ĐẾN 125 cm3 hoặc công suất động cơ điện đến 11 kW.'),
(126,1,'Quy định chung và quy tắc giao thông đường bộ','Người có Giấy phép lái xe mô tô hạng A được phép điều khiển loại xe nào dưới đây?',null,'["Xe mô tô hai bánh có dung tích xi-lanh đến 125 cm3 hoặc có công suất động cơ điện đến 11 kW.","Xe mô tô hai bánh có dung tích xi-lanh trên 125 cm3 hoặc có công suất động cơ điện trên 11 kW.","Cả hai ý trên."]'::jsonb,3,false,'Giấy phép lái xe hạng A cấp cho người điều khiển xe mô tô hai bánh có dung tích xi-lanh TRÊN 125 cm3 (hoặc xe điện trên 11 kW) và được phép điều khiển toàn bộ các loại xe quy định cho hạng A1.'),
(127,1,'Quy định chung và quy tắc giao thông đường bộ','Người có Giấy phép lái xe ô tô hạng B được phép điều khiển loại xe nào dưới đây?',null,'["Xe ô tô chở người đến 08 chỗ (không kể chỗ của người lái xe).","Xe ô tô tải và ô tô chuyên dùng có khối lượng toàn bộ theo thiết kế đến 3.500 kg.","Cả hai ý trên."]'::jsonb,3,false,'Hạng B (theo luật mới): Được lái ô tô chở người đến 8 chỗ (không kể ghế lái), ô tô tải và ô tô chuyên dùng có khối lượng toàn bộ theo thiết kế đến 3.500 kg; kéo rơ moóc đến 750 kg.'),
(128,1,'Quy định chung và quy tắc giao thông đường bộ','Người có Giấy phép lái xe hạng C1 được điều khiển loại xe nào dưới đây?',null,'["Xe ô tô tải và ô tô chuyên dùng có khối lượng toàn bộ theo thiết kế trên 7.500 kg; các loại xe ô tô tải quy định cho giấy phép lái xe hạng C1 kéo rơ moóc có khối lượng toàn bộ theo thiết kế đến 750 kg.","Xe ô tô tải và ô tô chuyên dùng có khối lượng toàn bộ theo thiết kế trên 3.500 kg đến 7.500 kg; các loại xe ô tô tải quy định cho giấy phép lái xe hạng C1 kéo rơ moóc có khối lượng toàn bộ theo thiết kế đến 750 kg.","Cả hai ý trên."]'::jsonb,2,false,'Hạng C1: Được cấp cho người lái xe ô tô tải và ô tô chuyên dùng có khối lượng toàn bộ từ TRÊN 3.500 kg ĐẾN 7.500 kg; kéo rơ moóc đến 750 kg.'),
(129,1,'Quy định chung và quy tắc giao thông đường bộ','Người có Giấy phép lái xe hạng C được điều khiển loại xe nào dưới đây?',null,'["Xe ô tô tải và ô tô chuyên dùng có khối lượng toàn bộ theo thiết kế trên 3.500 kg đến 7.500 kg; các loại xe ô tô tải quy định cho giấy phép lái xe hạng C1 kéo rơ moóc có khối lượng toàn bộ theo thiết kế đến 750 kg.","Xe ô tô tải và ô tô chuyên dùng có khối lượng toàn bộ theo thiết kế trên 7.500 kg; các loại xe ô tô tải quy định cho giấy phép lái xe hạng C kéo rơ moóc có khối lượng toàn bộ theo thiết kế đến 750 kg.","Cả hai ý trên."]'::jsonb,3,false,'Hạng C: Được lái ô tô tải và ô tô chuyên dùng có khối lượng toàn bộ TRÊN 7.500 kg và toàn bộ các loại xe quy định cho hạng C1; kéo rơ moóc đến 750 kg.'),
(130,1,'Quy định chung và quy tắc giao thông đường bộ','Người có Giấy phép lái xe hạng D1 được điều khiển loại xe nào dưới đây?',null,'["Xe ô tô chở người (kể cả xe buýt) trên 16 chỗ (không kể chỗ của người lái xe) đến 29 chỗ (không kể chỗ của người lái xe); các loại xe ô tô chở người quy định cho giấy phép lái xe hạng D1 kéo rơ moóc có khối lượng toàn bộ theo thiết kế đến 750 kg.","Xe ô tô chở người trên 08 chỗ (không kể chỗ của người lái xe) đến 16 chỗ (không kể chỗ của người lái xe); các loại xe ô tô chở người quy định cho giấy phép lái xe hạng D1 kéo rơ moóc có khối lượng toàn bộ theo thiết kế đến 750 kg.","Cả hai ý trên."]'::jsonb,2,false,'Hạng D1: Được lái ô tô chở người từ TRÊN 8 CHỖ ĐẾN 16 CHỖ (không kể ghế lái); kéo rơ moóc đến 750 kg.'),
(131,1,'Quy định chung và quy tắc giao thông đường bộ','Người có Giấy phép lái xe hạng D2 được điều khiển loại xe nào dưới đây?',null,'["Xe ô tô chở người (kể cả xe buýt) trên 16 chỗ (không kể chỗ của người lái xe) đến 29 chỗ (không kể chỗ của người lái xe); các loại xe ô tô chở người quy định cho giấy phép lái xe hạng D2 kéo rơ moóc có khối lượng toàn bộ theo thiết kế đến 750 kg.","Xe ô tô chở người trên 08 chỗ (không kể chỗ của người lái xe) đến 16 chỗ (không kể chỗ của người lái xe); các loại xe ô tô chở người quy định cho giấy phép lái xe hạng D1 kéo rơ moóc có khối lượng toàn bộ theo thiết kế đến 750 kg.","Cả hai ý trên."]'::jsonb,3,false,'Hạng D2: Được lái ô tô chở người từ TRÊN 16 CHỖ ĐẾN 29 CHỖ (kể cả xe buýt); và toàn bộ xe quy định cho hạng D1; kéo rơ moóc đến 750 kg.'),
(132,1,'Quy định chung và quy tắc giao thông đường bộ','Người có Giấy phép lái xe hạng D được điều khiển loại xe nào dưới đây?',null,'["Xe ô tô chở người (kể cả xe buýt) trên 29 chỗ (không kể chỗ của người lái xe); xe ô tô chở người giường nằm; các loại xe ô tô chở người quy định cho giấy phép lái xe hạng D kéo rơ moóc có khối lượng toàn bộ theo thiết kế đến 750 kg.","Xe ô tô chở người (kể cả xe buýt) trên 16 chỗ (không kể chỗ của người lái xe) đến 29 chỗ (không kể chỗ của người lái xe).","Các loại xe ô tô quy định cho giấy phép lái xe hạng C kéo rơ moóc có khối lượng toàn bộ theo thiết kế trên 750 kg; xe ô tô đầu kéo kéo sơ mi rơ moóc.","Ý 1 và ý 2."]'::jsonb,4,false,'Hạng D: Được lái xe chở khách TRÊN 29 CHỖ, xe giường nằm và toàn bộ các loại xe quy định cho các hạng B, C1, C, D1, D2.'),
(133,1,'Quy định chung và quy tắc giao thông đường bộ','Người có Giấy phép lái xe hạng BE được điều khiển loại xe nào dưới đây?',null,'["Xe ô tô chở người (kể cả xe buýt) trên 29 chỗ (không kể chỗ của người lái xe); xe ô tô chở người giường nằm.","Các loại xe ô tô quy định cho giấy phép lái xe hạng B kéo rơ moóc có khối lượng toàn bộ theo thiết kế trên 750 kg.","Xe ô tô chở người (kể cả xe buýt) trên 16 chỗ (không kể chỗ của người lái xe) đến 29 chỗ (không kể chỗ của người lái xe); các loại xe ô tô chở người quy định cho giấy phép lái xe hạng D2 kéo rơ moóc có khối lượng toàn bộ theo thiết kế đến 750 kg."]'::jsonb,2,false,'Hạng BE: Cấp cho người đã có GPLX hạng B để kéo thêm rơ moóc có khối lượng toàn bộ TRÊN 750 kg.'),
(134,1,'Quy định chung và quy tắc giao thông đường bộ','Người có Giấy phép lái xe hạng CE được điều khiển loại xe nào dưới đây?',null,'["Các loại xe ô tô quy định cho giấy phép lái xe hạng C kéo rơ moóc có khối lượng toàn bộ theo thiết kế trên 750 kg; xe ô tô đầu kéo kéo sơ mi rơ moóc.","Các loại xe ô tô quy định cho giấy phép lái xe hạng D1 kéo rơ moóc có khối lượng toàn bộ theo thiết kế trên 750 kg.","Cả hai ý trên."]'::jsonb,1,false,'Hạng CE: Cấp cho người đã có GPLX hạng C để kéo thêm rơ moóc có khối lượng toàn bộ TRÊN 750 kg, hoặc lái xe ô tô đầu kéo kéo sơ mi rơ moóc.'),
(135,1,'Quy định chung và quy tắc giao thông đường bộ','Người có Giấy phép lái xe hạng DE được điều khiển loại xe nào dưới đây?',null,'["Các loại xe ô tô quy định cho giấy phép lái xe hạng D kéo rơ moóc có khối lượng toàn bộ theo thiết kế trên 750 kg; xe ô tô chở khách nối toa.","Các loại xe ô tô quy định cho giấy phép lái xe hạng C kéo rơ moóc có khối lượng toàn bộ theo thiết kế trên 750 kg; xe ô tô đầu kéo kéo sơ mi rơ moóc.","Cả hai ý trên."]'::jsonb,1,false,'Hạng DE: Cấp cho người đã có GPLX hạng D để kéo thêm rơ moóc có khối lượng toàn bộ TRÊN 750 kg, hoặc điều khiển ô tô chở khách nối toa.'),
(136,1,'Quy định chung và quy tắc giao thông đường bộ','Người tập lái xe ô tô khi tham gia giao thông đường bộ phải bảo đảm các điều kiện nào dưới đây?',null,'["Phải thực hành trên xe tập lái, trên tuyến đường tập lái và có giáo viên dạy lái bảo trợ tay lái.","Phải mang theo giấy phép xe tập lái.","Cả hai ý trên."]'::jsonb,1,false,'Người tập lái ô tô khi tham gia giao thông bắt buộc phải thực hành trên xe tập lái có gắn biển ''TẬP LÁI'', chạy trên các tuyến đường được phê duyệt tập lái và có giáo viên dạy lái ngồi bên cạnh bảo trợ tay lái.'),
(137,1,'Quy định chung và quy tắc giao thông đường bộ','Người lái xe khi tham gia giao thông đường bộ phải đảm bảo các điều kiện nào dưới đây?',null,'["Phải đủ tuổi, sức khỏe theo quy định của pháp luật; có giấy phép lái xe đang còn điểm, còn hiệu lực phù hợp với loại xe đang điều khiển do cơ quan có thẩm quyền cấp (trừ người lái xe gắn máy).","Phải là người đứng tên trong đăng ký xe.","Cả hai ý trên."]'::jsonb,1,false,'Người lái xe khi tham gia giao thông phải đủ độ tuổi, có đủ sức khỏe và sở hữu Giấy phép lái xe hợp lệ (đang còn điểm và còn hạn sử dụng) phù hợp với loại xe đang điều khiển.'),
(138,1,'Quy định chung và quy tắc giao thông đường bộ','Khi tham gia giao thông đường bộ, người lái xe phải mang theo các giấy tờ gì?',null,'["Chứng nhận đăng ký xe hoặc bản sao Chứng nhận đăng ký xe có chứng thực kèm bản gốc giấy tờ xác nhận của tổ chức tín dụng, chi nhánh ngân hàng nước ngoài còn hiệu lực trong trường hợp xe đang được thế chấp tại tổ chức tín dụng, chi nhánh ngân hàng nước ngoài.","Giấy phép lái xe phù hợp với loại xe đang điều khiển; chứng nhận kiểm định an toàn kỹ thuật và bảo vệ môi trường đối với xe cơ giới theo quy định của pháp luật; chứng nhận bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới.","Trường hợp các giấy tờ nêu trên đã được tích hợp vào tài khoản định danh điện tử thì việc xuất trình, kiểm tra có thể thực hiện thông qua tài khoản định danh điện tử.","Cả ba ý trên."]'::jsonb,4,false,'Khi lái xe, người lái phải mang theo: Đăng ký xe (hoặc bản sao kèm biên bản ngân hàng thế chấp), GPLX, Chứng nhận đăng kiểm và Bảo hiểm TNDS bắt buộc. Trường hợp các giấy tờ đã tích hợp trên VNeID thì việc xuất trình qua VNeID có giá trị tương đương.'),
(139,1,'Quy định chung và quy tắc giao thông đường bộ','Giấy phép lái xe bị thu hồi trong các trường hợp nào sau đây?',null,'["Người được cấp giấy phép lái xe không đủ điều kiện sức khỏe theo kết luận của cơ sở khám bệnh, chữa bệnh đối với từng hạng giấy phép lái xe.","Giấy phép lái xe được cấp sai quy định.","Giấy phép lái xe đã quá thời hạn tạm giữ hoặc hết thời hiệu thi hành quyết định xử phạt vi phạm hành chính theo quy định của pháp luật về xử lý vi phạm hành chính nếu người vi phạm không đến nhận mà không có lý do chính đáng.","Cả ba ý trên."]'::jsonb,4,false,'GPLX bị thu hồi khi: Không đủ điều kiện sức khỏe theo kết luận y tế; GPLX được cấp sai quy định; hoặc quá thời hạn tạm giữ/hết thời hiệu xử phạt mà người vi phạm không đến nhận không có lý do chính đáng.'),
(140,1,'Quy định chung và quy tắc giao thông đường bộ','Người có giấy phép lái xe chưa bị trừ hết 12 điểm, được phục hồi điểm giấy phép lái xe trong trường hợp nào sau đây?',null,'["Không được phục hồi.","Được phục hồi đủ 12 điểm, nếu không bị trừ điểm trong thời hạn 12 tháng từ ngày bị trừ điểm gần nhất."]'::jsonb,2,false,'Quy định trừ điểm bằng lái: Người có GPLX chưa bị trừ hết 12 điểm sẽ được TỰ ĐỘNG PHỤC HỒI ĐỦ 12 ĐIỂM nếu trong thời hạn 12 tháng kể từ ngày bị trừ điểm gần nhất không bị trừ thêm điểm nào.'),
(141,1,'Quy định chung và quy tắc giao thông đường bộ','Người có giấy phép lái xe đã bị trừ hết điểm phải làm gì để phục hồi điểm giấy phép lái xe?',null,'["Không vi phạm pháp luật trật tự, an toàn giao thông đường bộ trong thời gian 12 tháng kể từ ngày bị trừ hết điểm.","Sau thời hạn ít nhất là 06 tháng kể từ ngày bị trừ hết điểm, người có phép lái xe được tham gia kiểm tra nội dung kiến thức pháp luật về trật tự, an toàn giao thông đường bộ theo quy định, có kết quả đạt yêu cầu thì được phục hồi đủ 12 điểm.","Cả hai ý trên."]'::jsonb,2,false,'Nếu bị trừ hết 12 điểm: Sau thời hạn ÍT NHẤT 06 THÁNG kể từ ngày bị trừ hết điểm, người lái xe phải tham gia kiểm tra lại kiến thức pháp luật về TTATGT đường bộ, khi đạt yêu cầu mới được phục hồi đủ 12 điểm.'),
(142,1,'Quy định chung và quy tắc giao thông đường bộ','Trách nhiệm của tổ chức, cá nhân đứng tên trong giấy chứng nhận đăng ký xe khi chưa thực hiện thu hồi chứng nhận đăng ký xe, biển số xe được quy định như thế nào?',null,'["Tiếp tục chịu trách nhiệm của chủ xe.","Không chịu trách nhiệm sau khi đã chuyển nhượng, trao đổi, tặng, cho."]'::jsonb,1,false,'Chủ xe đứng tên trên Giấy chứng nhận đăng ký xe khi mua bán, chuyển nhượng mà chưa làm thủ tục thu hồi đăng ký, biển số thì vẫn phải TIẾP TỤC CHỊU MỌI TRÁCH NHIỆM pháp lý của chủ xe.'),
(143,1,'Quy định chung và quy tắc giao thông đường bộ','Để bảo đảm điều kiện tham gia giao thông đường bộ, loại phương tiện nào phải lắp thiết bị giám sát hành trình?',null,'["Xe ô tô kinh doanh vận tải.","Xe ô tô chở người từ 08 chỗ trở lên (không kể chỗ của người lái xe) kinh doanh vận tải, xe ô tô đầu kéo, xe cứu thương.","Cả hai ý trên."]'::jsonb,3,true,'🚨 [CÂU ĐIỂM LIỆT] Xe bắt buộc phải lắp thiết bị giám sát hành trình (hộp đen): Toàn bộ xe ô tô kinh doanh vận tải (chở khách từ 8 chỗ trở lên, xe đầu kéo, xe tải chở hàng...) và xe cứu thương để kiểm soát lộ trình và an toàn giao thông.'),
(144,1,'Quy định chung và quy tắc giao thông đường bộ','Tốc độ khai thác tối đa cho phép đối với xe máy chuyên dùng, xe gắn máy và các loại xe tương tự tham gia giao thông trên đường bộ (trừ đường cao tốc) là bao nhiêu km/h?',null,'["50 km/h.","40 km/h.","60 km/h."]'::jsonb,2,false,'Xe máy chuyên dùng, xe gắn máy (kể cả xe máy điện) khi tham gia giao thông trên đường bộ chỉ được chạy với tốc độ tối đa cho phép là 40 km/h.'),
(145,1,'Quy định chung và quy tắc giao thông đường bộ','Trên đường bộ, trong khu vực đông dân cư, đường đôi hoặc đường một chiều có từ hai làn xe cơ giới trở lên, xe mô tô hai bánh, ô tô chở người đến 28 chỗ không kể chỗ của người lái xe tham gia giao thông với tốc độ khai thác tối đa cho phép là bao nhiêu?',null,'["60 km/h.","50 km/h.","40 km/h."]'::jsonb,1,false,'Trong khu đông dân cư trên đường đôi (hoặc đường một chiều có từ 2 làn xe cơ giới trở lên): Tốc độ tối đa của ô tô con, xe mô tô, ô tô chở người đến 28 chỗ là 60 km/h.'),
(146,1,'Quy định chung và quy tắc giao thông đường bộ','Trên đường bộ (trừ đường cao tốc) trong khu vực đông dân cư, đường hai chiều hoặc đường một chiều có một làn xe cơ giới, xe mô tô hai bánh, ô tô chở người đến 28 chỗ không kể chỗ của người lái xe tham gia giao thông với tốc độ khai thác tối đa cho phép là bao nhiêu?',null,'["60 km/h.","50 km/h.","40 km/h."]'::jsonb,2,false,'Trong khu đông dân cư trên đường hai chiều (hoặc đường một chiều có 1 làn xe cơ giới): Tốc độ tối đa của ô tô con, xe mô tô, ô tô chở người đến 28 chỗ là 50 km/h.'),
(147,1,'Quy định chung và quy tắc giao thông đường bộ','Trên đường bộ (trừ đường cao tốc) trong khu vực đông dân cư, đường hai chiều hoặc đường một chiều có một làn xe cơ giới, loại xe nào dưới đây được tham gia giao thông với tốc độ khai thác tối đa cho phép là 50 km/h?',null,'["Ô tô tải, ô tô chở người trên 28 chỗ không kể chỗ của người lái xe.","Xe gắn máy, xe máy chuyên dùng.","Cả hai ý trên."]'::jsonb,1,false,'Trong khu đông dân cư trên đường 2 chiều (hoặc 1 chiều 1 làn xe cơ giới): Ô tô tải, xe khách trên 28 chỗ được chạy tốc độ tối đa là 50 km/h (riêng xe gắn máy luôn chỉ được chạy tối đa 40 km/h).'),
(148,1,'Quy định chung và quy tắc giao thông đường bộ','Trên đường bộ (trừ đường cao tốc) trong khu vực đông dân cư, đường đôi hoặc đường một chiều có từ hai làn cơ giới trở lên, loại xe nào dưới đây được tham gia giao thông với tốc độ khai thác tối đa là 60 km/h?',null,'["Ô tô tải, ô tô chở người trên 28 chỗ không kể chỗ của người lái xe.","Xe gắn máy, xe máy chuyên dùng.","Cả hai ý trên."]'::jsonb,1,true,'🚨 [CÂU ĐIỂM LIỆT] Trong khu đông dân cư trên đường đôi (hoặc 1 chiều có từ 2 làn cơ giới): Ô tô tải, ô tô khách trên 28 chỗ được chạy tốc độ tối đa là 60 km/h.'),
(149,1,'Quy định chung và quy tắc giao thông đường bộ','Trên đường bộ (trừ đường cao tốc) ngoài khu vực đông dân cư, đường đôi hoặc đường một chiều có từ hai làn xe cơ giới trở lên, loại xe nào dưới đây được tham gia giao thông với tốc độ khai thác tối đa cho phép là 90 km/h?',null,'["Xe ô tô chở người đến 28 chỗ không kể chỗ của người lái xe (trừ xe buýt); ô tô tải có trọng tải không lớn hơn 3,5 tấn.","Xe ô tô chở người trên 28 chỗ không kể chỗ người lái xe (trừ xe buýt); ô tô tải có trọng tải trên 3,5 tấn (trừ ô tô xi téc).","Xe buýt; ô tô đầu kéo kéo sơ mi rơ moóc (trừ ô tô đầu kéo kéo sơ mi rơ moóc xi téc); xe mô tô; ô tô chuyên dùng (trừ ô tô trộn vữa, ô tô trộn bê tông lưu động)."]'::jsonb,1,false,'Ngoài khu đông dân cư trên đường đôi có dải phân cách giữa: Tốc độ tối đa 90 km/h áp dụng cho xe ô tô chở người đến 28 chỗ (trừ buýt) và ô tô tải có trọng tải đến 3,5 tấn.'),
(150,1,'Quy định chung và quy tắc giao thông đường bộ','Trên đường bộ ngoài khu vực đông dân cư, đường đôi hoặc đường một chiều có từ hai làn xe cơ giới trở lên (trừ đường cao tốc) loại xe nào dưới đây được tham gia giao thông với tốc độ khai thác tối đa cho phép là 80 km/h?',null,'["Xe ô tô chở người đến 28 chỗ không kể chỗ của người lái xe (trừ xe buýt); ô tô tải có trọng tải không lớn hơn 3,5 tấn.","Xe ô tô chở người trên 28 chỗ không kể chỗ người lái xe (trừ xe buýt); ô tô tải có trọng tải trên 3,5 tấn (trừ ô tô xi téc).","Xe buýt; ô tô đầu kéo kéo sơ mi rơ moóc (trừ ô tô đầu kéo kéo sơ mi rơ moóc xi téc); xe mô tô; ô tô chuyên dùng (trừ ô tô trộn vữa, ô tô trộn bê tông lưu động).","Ô tô kéo rơ moóc; ô tô kéo xe khác; ô tô trộn vữa, ô tô trộn bê tông lưu động, ô tô xi téc, ô tô đầu kéo kéo sơ mi rơ moóc xi téc, ô tô kéo theo rơ moóc xi téc)."]'::jsonb,2,false,'Ngoài khu đông dân cư trên đường đôi có dải phân cách giữa: Tốc độ tối đa 80 km/h áp dụng cho xe ô tô chở người trên 28 chỗ và ô tô tải có trọng tải trên 3,5 tấn.'),
(151,1,'Quy định chung và quy tắc giao thông đường bộ','Trên đường bộ ngoài khu vực đông dân cư, đường đôi hoặc đường một chiều có từ hai làn xe cơ giới trở lên (trừ đường cao tốc) loại xe nào dưới đây được tham gia giao thông với tốc độ khai thác tối đa cho phép là 70 km/h?',null,'["Xe ô tô chở người đến 28 chỗ không kể chỗ của người lái xe (trừ xe buýt); ô tô tải có trọng tải không lớn hơn 3,5 tấn.","Xe ô tô chở người trên 28 chỗ không kể chỗ người lái xe (trừ xe buýt); ô tô tải có trọng tải trên 3,5 tấn (trừ ô tô xi téc).","Xe buýt; ô tô đầu kéo kéo sơ mi rơ moóc (trừ ô tô đầu kéo kéo sơ mi rơ moóc xi téc); xe mô tô; ô tô chuyên dùng (trừ ô tô trộn vữa, ô tô trộn bê tông lưu động).","Ô tô kéo rơ moóc; ô tô kéo xe khác; ô tô trộn vữa, ô tô trộn bê tông lưu động, ô tô xi téc, ô tô đầu kéo kéo sơ mi rơ moóc xi téc, ô tô kéo theo rơ moóc xi téc."]'::jsonb,3,true,'🚨 [CÂU ĐIỂM LIỆT] Ngoài khu đông dân cư trên đường đôi có dải phân cách giữa: Tốc độ tối đa 70 km/h áp dụng cho xe buýt, xe đầu kéo kéo sơ mi rơ moóc, xe mô tô và ô tô chuyên dùng.'),
(152,1,'Quy định chung và quy tắc giao thông đường bộ','Trên đường bộ ngoài khu vực đông dân cư, đường đôi hoặc đường một chiều có từ hai làn xe cơ giới trở lên (trừ đường cao tốc) loại xe nào dưới đây được tham gia giao thông với tốc độ khai thác tối đa cho phép là 60 km/h?',null,'["Xe ô tô chở người đến 28 chỗ không kể chỗ của người lái xe (trừ xe buýt); ô tô tải có trọng tải không lớn hơn 3,5 tấn.","Xe ô tô chở người trên 28 chỗ không kể chỗ người lái xe (trừ xe buýt); ô tô tải có trọng tải trên 3,5 tấn (trừ ô tô xi téc).","Xe buýt; ô tô đầu kéo kéo sơ mi rơ moóc (trừ ô tô đầu kéo kéo sơ mi rơ moóc xi téc); xe mô tô; ô tô chuyên dùng (trừ ô tô trộn vữa, ô tô trộn bê tông lưu động).","Ô tô kéo rơ moóc; ô tô kéo xe khác; ô tô trộn vữa, ô tô trộn bê tông lưu động, ô tô xi téc, ô tô đầu kéo kéo sơ mi rơ moóc xi téc, ô tô kéo theo rơ moóc xi téc."]'::jsonb,4,false,'Ngoài khu đông dân cư trên đường đôi có dải phân cách giữa: Tốc độ tối đa 60 km/h áp dụng cho các loại xe kéo rơ moóc, kéo xe khác, ô tô trộn vữa, ô tô xi téc.'),
